window.__XINYU_PSYCH_KB__ = {"version":"v1.4","built":"r129","counts":{"A":37,"B":46,"C":17,"D":27},"excludedE":0,"sourceFiles":21,"entries":[{"id":"PSY-FE-001","title":"FACS：面部动作编码系统与动作单元（AU）","level":"A","summary":"FACS 把表情拆成约 46 个肌肉级「动作单元（AU）」，是表情研究的中立度量衡；它编码动作而非情绪，「AU→情绪」映射是另一回事。","content":"FACS 由 Paul Ekman 与 Wallace Friesen 1978 年提出（方法论吸收瑞典解剖学家 Hjortsjö 1969 的解剖学工作），2002 年由 Ekman/Friesen/Hager 修订为《FACS: The Manual》，至今仍是行为科学表情测量的标准工具。AU = 把每块面部肌肉的可观察动作编成最小编号：AU1=眉头内侧上提（发愁）、AU4=皱眉、AU6=脸颊上提（眼角笑）、AU12=嘴角上拉；AU6+AU12 同现即「杜兴式微笑」（真笑：眼角+嘴角一起动）。计数口径：文献常引约 46 个 AU（另有口径把面部本体肌肉动作记 28 个主 AU、再加头部/眼球动作码），随版本与计数方式而异。","rel":[]},{"id":"PSY-FE-005","title":"Duchenne 真笑标记：感知层有效，「真心指标」有效度争议","level":"D","summary":"心屿 smileKind/masking 判据（AU12+AU6/AU7 比值 0.20）的心理学原型与效度边界：真笑标记在「观察者感知真诚」层面有效，但作为「真心指标」存在强度伪影争议，产品措辞必须用「可能」。","content":"本项目表情侧判据的心理学原型：真笑（Duchenne 笑）= 口部 AU12（颧大肌，对应 blendshape mouthSmile）+ 眼周 AU6/AU7（眼轮匝肌眶部，对应 cheekSquint/eyeSquint）同时参与；社交性微笑只有口部。心屿据此立了三态判据 smileKind（face-engine.js:84-100）：口部微笑<0.35=未检出；眼周/口部比值≥0.20=真笑，否则社交性微笑；社交笑且紧张线索（抿唇/压眉）≥0.30⇒masking=强颜欢笑嫌疑（app.js:129 文案用「可能是强颜欢笑」）。","rel":["fear"]},{"id":"PSY-FE-010","title":"端侧面部推理的可用信号：478 关键点与 52 维 blendshape","level":"B","summary":"浏览器端 MediaPipe FaceLandmarker 可稳定拿到 478 点人脸网格与 52 维 blendshape（近似 AU 强度），模型+运行时约 13.7MB 且可惰性加载，这是端侧情绪/微表情特征的全部原料。","content":"478 点=468 网格+10 虹膜；52 维 blendshape 为 0~1 系数（近似 FACS 的 AU），输入 256×256 裁剪脸。本仓一手实测：face_landmarker.task 3,758,596B + vision_wasm_internal.wasm 9,574,032B 等合计 13,674,721B，惰性加载（用户点开才下），GPU 优先 CPU 回落，WASM SIMD 探测门（不达标明示降级）。运行口径：8fps 轮询、EMA α=0.3、读数有效期 3000ms。","rel":[]},{"id":"PSY-FE-015","title":"表情识别准确率：实验室基准与真实场景的落差","level":"B","summary":"表情识别存在三层落差：摆拍基准 SOTA 90%+、自然场景大数据 63-66%、而真实自发场景中面部构型与情绪的共现率仅约19%。","content":"硬数据：三层基准给天花板：摆拍精选 RAF-DB（约3万张）SOTA≈90–92%、老混合基准 FER2013 自报单网 SOTA≈73.28%（人类仅65–68%；Khaireddin & Chen 2021 原文口径）、自然场景 AffectNet 8类 SOTA≈63–66%（2024-2025 综述，2026-10-11 检索）。自发真实场景给地板：Barrett 等顶刊综述（PSPI 20(1):1-68，PMC6640856 原文实读）发现实验室自发场景中假设面部构型仅在 19%（.15-.25）的对应情绪事件出现（r=.32）；真实格斗赛后仅 8/55、25/119 名胜者露 Duchenne 真笑；","rel":[]},{"id":"PSY-FE-016","title":"遮挡（口罩）显著削弱情绪识别","level":"B","summary":"口罩遮挡使人脸情绪识别下降约20个百分点（人因研究 88%→68%；机器方法约70.76%），遮挡应显式提示而非继续输出分类。","content":"两类证据一致：人因研究（Face masks impair facial emotion recognition and induce specific emotion confusions, 2022）显示口罩使人脸情绪识别 88%→68%，约掉 20 个百分点，且损伤随情绪类别不同（依赖嘴部线索的情绪掉得更多）；机器方法（Elsayed et al. 2023, PMC10067009）在口罩下 3 类情绪识别 70.76%。","rel":[]},{"id":"PSY-FE-002","title":"微表情：定义、时长边界与「泄漏」证据","level":"A","summary":"微表情=1/25–1/5 秒（约 40–200ms）泄露隐藏情绪的面部动作；但「测谎级可靠指标」被高估——有单研究显示真实伪装样本中标准全脸微表情仅约 2%。","content":"历史：Haggard & Isaacs（1966）逐帧审看心理治疗影片时最早注意到这类「瞬时表情（micromomentary expressions）」；Ekman & Friesen（1969）在〈Nonverbal leakage and clues to deception〉（Psychiatry）提出 micro-expression 一词。通行界定：持续时间约 1/25–1/5 秒、细微、揭示「试图掩盖的情绪」（Shen 等 2012 摘要定义句原词；Ekman 官网口径为「不到一秒的无意识泄漏」）。","rel":[]},{"id":"PSY-FE-003","title":"微表情的神经机制证据：多为间接外推，缺直接证据","level":"C","summary":"杏仁核（恐惧/眼区）、阈下面孔加工、抑制的生理代价是可信但间接的外推证据；「检测到微表情=读出情绪」没有直接神经证据。","content":"目前没有对自发性微表情的直接神经影像证据；主流「脑机制」证据是从一般面孔情绪加工外推：①杏仁核对威胁识别关键——病例 SM 双侧杏仁核损伤后注视模式不走眼区、识别不了恐惧，引导其注视眼区后恢复（Adolphs 等 2005，Nature 433(7021):25-26）；②阈下加工真实存在——恐惧面孔经后向掩蔽（紧随中性脸盖住）到意识阈下仍激活杏仁核（Whalen 等 1998，J Neurosci 18(1):411-418；Morris 等 1998，Nature 393:467-470）——这给「短暂到不死意识的微表情也能被加工」提供了神经合理性，但这是阈下刺激范式，不等于微表情本身的直接证据；","rel":["fear"]},{"id":"PSY-FE-006","title":"微表情作为测谎/意图识别证据：科学证据不足且学界分裂","level":"D","summary":"「微表情测谎」缺乏可靠科学证据（Burgoon 2018），Matsumoto 阵营有异议——故表情证据在「真实意图识别」场景只能触发探询，永远不能输出「你在撒谎」类断言，危机判定不得被表情介入。","content":"「微表情泄露真实情绪、可用于识谎」是流行文化盛传的说法（《Lie to Me》等），但科学证据不站在它一边。批评方：Burgoon, J. K. (2018, Frontiers in Psychology 9:1672，观点文) 论证微表情既非测谎的有效手段也非可靠手段——「无法控制的情绪泄露」假设本身存疑；二手综述常引「单靠微表情测谎准确率仅约 54%、略高于随机」（二手转述，未核对一手，按 C 级对待）。Ekman 本人亦承认单条微表情不可定论（「Othello 错误」：把真焦虑误读成说谎信号）。","rel":["fear"]},{"id":"PSY-FE-007","title":"微表情作为「读心/抓谎」线索的效度争议（两方）","level":"D","summary":"批评方认为微表情罕见、不可靠、不构成欺骗证据（微软 2022 年停售情绪识别即引此理）；Ekman 传统与 MER 社区则持续产出跨文化证据与识别模型——产品与答辩话术必须避开「读心」承诺。","content":"批评方：① Burgoon, J. K. (2018) 专文《Microexpressions Are Not the Best Way to Catch a Liar》：微表情太罕见、不可靠、且可被有意识控制，不构成可靠的欺骗线索；② 「奥赛罗错误」（Othello error）：无辜者的恐惧表情与说谎者的恐惧在脸上是一样的，读到情绪≠读到谎言；","rel":["fear"]},{"id":"PSY-FE-009","title":"微表情的时长定义与心屿现行采样架构的互斥","level":"A","summary":"微表情按 Ekman 定义只持续 40~200ms，心屿现行 8fps（125ms 间隔）采样 + EMA 平滑的架构在物理上捕捉不到它——上微表情必须整体换采样与判据架构，不是调参问题。","content":"微表情由 Ekman & Friesen (1969, Psychiatry 32(1):88-106) 定义为情绪被压抑时泄露的自发全脸表情，持续 1/25~1/5 秒（约 40~200ms），部分文献把上限放宽到 500ms。心屿现行面部管线是 8fps 采样（src/data/face-smile-rules.js:204 sample.fps=8，即每 125ms 才看一帧）：一次 40~200ms 的微表情至多落在 0~2 个样本里，随后还要过 EMA（指数移动平均，α=0.3，face-engine.js:213-218）平滑——瞬时信号会被当抖动抹掉。","rel":[]},{"id":"PSY-FE-011","title":"微表情时长边界与主流数据集规模","level":"A","summary":"微表情的通行操作定义是 ≤500ms 的无意识面部动作；主流数据集 CASME II（247 段/26 人/200fps）、SAMM（159 段/32 人）、CAS(ME)²（22 人长视频）、CAS(ME)³（80 小时/1,109 段微表情）全部为实验室引出、申请制研究用途。","content":"CASME II：247 段/26 人/200fps/640×480（脸区裁 280×340），收录标准=总时长<500ms 或 onset<250ms，5 类且极不均衡（disgust 60 段 vs sadness 7 段），onset-apex-offset 逐帧标注+双编码员 AU 一致性 0.846。SAMM：159 段/32 人/200fps/7 类。CAS(ME)²：Part A 约 93 长视频/22 人，30fps。CAS(ME)³（第三代）：约 80 小时/800 万帧/1,109 段微+3,490 段宏表达，Part A 100 名被试。SMIC：164 段/16 人/100fps。","rel":["sadness"]},{"id":"PSY-FE-018","title":"METT/SETT 微表情训练工具及其效度证据","level":"B","summary":"METT/SETT=Ekman 系微/细微表情训练工具（在线订阅 $119/3月起）；训练提升实验任务短暂表情判读有独立重复证据，但迁移到测谎无证据。","content":"是什么：METT（Micro Expression Training Tool）训练识别全脸短暂表情；SETT（Subtle Expression Training Tool）训练识别局限于单一面部区域（眉/眼睑/脸颊/鼻/唇）的「迷你」表情。现售于 Paul Ekman Group 官网「Micro Expressions Training Tools」在线订阅：Face Basics $119/3 个月（含升级版 METT+SETT），页面目标用户明写警察/安保等「评估真实性、侦测欺骗」需求（2026-10-11 亲手打开该页核实）。","rel":[]},{"id":"PSY-FE-019","title":"Bond & DePaulo (2006)：人类谎言识别平均准确率约 54%","level":"A","summary":"206 项研究、24,483 名评判者：人类无辅助测谎平均准确率 54%（真话 61%/谎言 47%），个体能力差异<1 个百分点——永远不输出「你在撒谎」。","content":"数字：Bond & DePaulo (2006, Personality and Social Psychology Review 10(3):214-234，PubMed 摘要亲核，PMID 16859438) 汇总 206 份文献、24,483 名评判者：无辅助的谎言-真话判断平均正确率 54%——其中谎言只有 47% 被识破、真话 61% 被采信；听得到声音比只看画面更准；「有动机让人相信的人反而显得像在骗」。数字结构暴露「真话偏向（truth bias）」：人们默认对方诚实，代价是漏报谎言——对陪伴产品的镜像含义是「把沉默当没事」是系统性偏差。","rel":[]},{"id":"PSY-FE-004","title":"情绪普适性之争：Ekman 派 vs Barrett 派","level":"D","summary":"表情在效价/唤醒维度上跨文化较稳，但「皱眉=愤怒」式类别指纹在自然情境下不可靠（儿童愤怒情境皱眉仅 16.2%）；产品按「维度+情境+多模态」设计。","content":"普适方证据：Ekman & Friesen 1971（JPSP 17(2):124-129）对新几内亚南福尔部落（与西方媒体隔离的前文字文化）用故事匹配法，快乐/悲伤/愤怒/恐惧/惊讶/厌恶跨文化高一致；Ekman 1994〈Strong evidence for universals in facial expressions〉回应批评；","rel":["joy","sadness","anger","fear"]},{"id":"PSY-FE-008","title":"情绪识别的跨文化相对性（in-group advantage）","level":"B","summary":"97 项研究的元分析发现同文化情绪识别优势约+9.3%——表情读数带文化偏差，产品应靠置信度门限与分歧展示吸收而非硬校正。","content":"Elfenbein & Ambady 元分析 97 项研究：情绪识别既跨文化一致（超随机）又有文化特异性——同文化判断准确率比跨文化高约 9.3%，『情绪方言』（dialect theory）解释为文化显示规则造成的细微表达差异，同文化观察者学过这套方言。方法论质疑：Poortinga 等 (2002) 指出刺激/观察者抽样可能制造伪 in-group advantage。产品含义：①本仓 8fps blendshape 规则在训练者文化外的用户身上偏差未知；②答辩/演示对象若跨文化，读数偏差真实存在；","rel":[]},{"id":"PSY-AP-011","title":"微表情效度争议与产品边界（不测谎、不诊断）","level":"D","summary":"『微表情能否可靠泄露真实情绪』学界未决：Porter & ten Brinke (2008) 有受控实证支持泄漏现象，Barrett et al. (2019) 与 Burgoon et al. (2018) 认为不可靠；产品上表情读数只能当陪伴线索，禁做测谎/诊断，危机恒由文本判。","content":"支持方：Porter & ten Brinke (2008, Psychological Science 19(5):508-514) 在受控掩蔽情绪实验中记录到短暂的『泄漏』微表情，且伪造表情常不完整——微表情现象有实证基础。反对方：Barrett, Adolphs, Marsella, Martinez & Pollak (2019, Psychological Science in the Public Interest 20(1):1-68) 系统综述认为面部动作不是情绪的可靠指纹、随情境与个体变化，微表情测谎缺乏可靠证据；Burgoon et al. (2018, PMC) 直接以『微表情不是抓谎的好办法』为题。","rel":[]},{"id":"PSY-SE-002","title":"情绪语义表征模型：基本情绪/评价理论/环形维度/建构论的一条主线","level":"A","summary":"离散类别管词典匹配与话术选择，效价×唤醒维度管可视化与连续追踪，评价理论管「情绪为什么发生」的归因——三者互补不互斥。","content":"①基本情绪/词典：Ekman 六类、Plutchik 1980 八情绪轮是情绪词典标注标准——NRC EmoLex（Mohammad & Turney 2013，Computational Intelligence 29(3):436-465）14,182 词×8 情绪（Plutchik 类）+2 极性；中文侧大连理工《情感词汇本体库》27,466 词、7 大类（乐/好/怒/哀/惧/恶/惊）21 小类、强度 1/3/5/7/9——心屿词典引擎可直接对标。","rel":[]},{"id":"PSY-SE-005","title":"评价理论深条目：Lazarus 初评/次评与核心关系主题","level":"A","summary":"情绪=对「利害+我能否应对」的两步认知评价：初评判目标关系，次评判应对资源——共情回复的「为什么」归因链，可直接写进 LLM 提示词。","content":"初评（primary appraisal）回答「这事跟我什么关系」：目标相关性（跟我的利害沾不沾边）、目标一致性（帮我还是害我）、自我卷入类型（伤自尊还是伤价值观）。次评（secondary appraisal）回答「我怎么办」：归因/责怪、应对潜力（我搞得定吗）、未来预期（会更糟还是更好）。两者合起来决定情绪「是什么」和「有多强」——框架出自 Lazarus《Emotion and Adaptation》(1991) 与 Lazarus & Folkman《Stress, Appraisal, and Coping》(1984)。","rel":[]},{"id":"PSY-SE-006","title":"环形模型深条目：Russell 1980 效价×唤醒与核心情感","level":"A","summary":"效价×唤醒是情绪的「经纬度」：Russell 1980 把情绪词排成环形，四象限=兴奋/紧张/平静/消沉——连续读数直接驱动星雾与情绪曲线。","content":"结构：对情绪形容词自评数据做因素分析，情绪词不是各管各的，而是绕一个圆周排列——两个正交维度：效价（愉悦↔不愉悦）与唤醒（激活↔去激活）；四象限即「高唤醒-负效价（紧张/烦躁）」「高唤醒-正效价（兴奋/惊讶）」「低唤醒-正效价（平静/放松）」「低唤醒-负效价（消沉/倦怠）」。","rel":["joy","anger","fear","calm"]},{"id":"PSY-SE-007","title":"情绪建构论深条目：Barrett 建构论与基本情绪论之争（两方）","level":"D","summary":"建构论：情绪是「核心情感+概念/语言+社会现实」即时组装的类别，否认天生情绪指纹；基本情绪派反驳——活的理论分歧，两方证据都要收。","content":"主张方（建构论）：情绪不是天生的自然类（natural kinds）——Barrett (2006, Perspectives on Psychological Science 1(1):28-58，Crossref 核实，被引 3,000+) 系统论证「愤怒/恐惧等经典类别没有跨情境不变的生物指纹」；情绪=核心情感（效价×唤醒，见 [[PSY-SE-006]]）+ 概念系统用语言与情境即时「组装」出类别体验（Barrett 2017《How Emotions Are Made》, Houghton Mifflin Harcourt）+ 社会现实（文化提供情绪概念）。","rel":["anger","fear"]},{"id":"PSY-SE-001","title":"具身认知与情绪：grounded cognition 与面部反馈的复制史","level":"B","summary":"情绪概念部分根植于身体状态的重演（Barsalou/Niedenthal）；面部反馈效应小而真实（d≈0.2）但范式依赖（铅笔法失效）——产品不得宣传为情绪调节手段。","content":"核心主张：概念不在抽象符号库里，是感知-动作经验的「部分重演」——Barsalou 1999〈Perceptual Symbol Systems〉（Behavioral and Brain Sciences）、2008〈Grounded Cognition〉（Annual Review of Psychology）。Niedenthal 2007（Science 316(5827):1002-1005）把该框架用于情绪：识别表情涉及观察者自身的面部/躯体模拟。","rel":[]},{"id":"PSY-SE-003","title":"语用推理：会话含义与关联理论——「话里有话」的情绪理解","level":"A","summary":"Grice 四准则的违反/搁置产生会话含义（「我没事」≠没事），关联理论用「认知效果/处理努力」解释话里有话；LLM 提示词应显式要求先判意图再选共情话术。","content":"Grice（1975，〈Logic and Conversation〉，收于 Cole & Morgan 主编 Syntax and Semantics Vol.3，Academic Press）：合作原则+四准则（质=不说自知虚假的话；量=信息不多不少；关系=说相关的话；方式=清晰无歧义）。准则被违反或搁置时，听者按「对方仍遵守合作原则」推出会话含义——「我没事」在质/量准则下推出相反含义；讽刺=公然违反质准则。关联理论（Sperber & Wilson 1986《Relevance: Communication and Cognition》，Blackwell；第二版 1995）：交际=明示-推理；关联=认知效果/处理努力之比；","rel":[]},{"id":"PSY-SE-004","title":"反讽/讽刺是 LLM 情绪判定的系统性弱项","level":"C","summary":"zero-shot LLM 讽刺检测 F1 仅约 0.5（近乎抛硬币），微调/思维链可到 80-90% 但结果离散——反讽是本仓 LLM 精判的系统性弱项。","content":"基准证据：SarcasmBench（arXiv:2408.11319，被引71+）系统评测 LLM 讽刺理解；zero-shot LLM 在 iSarcasm 类作者意图讽刺上 F1 仅约 0.507（OpenReview context-aware sarcasm 论文）；AAAI 2025 论文证明思维链（CoT）推理显著提升讽刺识别；微调后可达 80-90%（CLEF 2024 微调 Llama 3-8B 幽默分类 89.68%）——但数据集间复制不一致，故不入 B 级。机制：讽刺=字面义与意图义相反，属会话含义推理（Grice 语用），LLM 缺乏说话者历史与语境时天然弱。","rel":[]},{"id":"PSY-SE-008","title":"情绪粒度 emotional granularity：定义、证据与产品对接","level":"B","summary":"情绪粒度=用多细的情绪词区分自身感受的个体差异；粒度高者抑郁/焦虑更少、应对更好——心屿情绪分类与曲线可做成「粒度脚手架」。","content":"定义：情绪粒度（emotional granularity）指个体区分相似情绪状态的精细程度——从「我不爽」到「愤怒/委屈/失望/羞耻」能分多细；测量通常靠经验取样法：多次自评情绪词强度后算个体内相关，负相关越低=分化越细（Barrett 2004, JPSP 87(2):266-281，Crossref 核实；Kashdan, Barrett & McKnight 2015, Current Directions in Psychological Science 24(1):10-16，Crossref 核实，被引 360+）。","rel":["anger","fear"]},{"id":"PSY-AP-002","title":"公开微表情数据集的规模与许可红线","level":"B","summary":"CASME II 247 条/SAMM 159 条/SMIC 164 条，全部申请制、限学术非商用、禁再分发——用它们训练的模型随公网作品部署与商业化都踩许可红线，且每库被试仅 16~32 人，训不出跨人泛化的模型。","content":"规模（一手论文与官方库页交叉一致）：CASME II（中科院 2014）247 条/26 人/200fps 灰度；SAMM（曼彻斯特城市大学 2018，ACM TAFFC）159 条/32 人/200fps 彩色（另有 SAMM-LV 147 条长视频）；SMIC（奥卢大学 2013）164 条/16 人。许可：三者全部申请制——CASME II 需签 EULA，SAMM 需签 Release Agreement，均限定「非商业研究用途」并禁止再分发（SAMM 协议原文须向官方申请渠道取得；曾传公开链接已失效，见来源①与更正注）。性质分析（比赛作品用它们训练再部署是什么）：① 数据文件上公网 = 再分发，协议明确禁止，直接违约；","rel":[]},{"id":"PSY-AP-003","title":"人脸情绪分析的合规路径：PIPL 敏感信息制 + 2025 人脸办法 + 本地处理架构","level":"A","summary":"人脸情绪分析在中国法下属敏感个人信息处理：须单独同意+特定目的+充分必要性；本地处理降低泄露风险但不豁免合规，告知同意可做成每条都有代码对应物的可核验弹层。","content":"法律基线（2026-10-11 联网核实）：PIPL 第28条将人脸信息归入敏感个人信息（生物识别、宗教信仰、特定身份、医疗健康、金融账户、行踪及不满14周岁未成年人信息），处理须特定目的+充分必要性+严格保护措施；第29条要求单独同意。《人脸识别技术应用安全管理办法》（网信办+公安部，2025-06-01 施行）第6条：单独同意须充分知情前提下自愿明确作出；不得强制刷脸、须提供替代方式；存储超10万人备案；不满14周岁须监护人单独同意。对照：《生成式人工智能服务管理暂行办法》（2023-08-15 施行）第10条要求防未成年人过度依赖或沉迷（陪伴类应用直接相关）；","rel":[]},{"id":"PSY-AP-010","title":"学术微表情数据集许可与比赛作品使用边界","level":"B","summary":"CASME II/SAMM/CAS(ME)²/CAS(ME)³ 全部是申请审批制、限学术研究、禁再分发；用于训练方法论可以，把数据集原帧放进比赛提交物有违约风险，演示与部署应只用自采同意数据。","content":"CASME II：官网填申请表+上传签名许可协议，限研究用途（casme.psych.ac.cn）。SAMM：Bradford 表格申请，非商业研究。CAS(ME)²/CAS(ME)³：CAS 官方库页申请（melab.psych.ac.cn）。MER 系：签 EULA 后经邮箱发放（zeroqiaoba.github.io，MER2024）。合规用学术数据的正道=走 MEGC/MER 官方挑战通道。对 iCAN 的安全姿势：数据集只用于训练/评测方法论；演示视频与部署产品只用自采且获同意的数据。","rel":[]},{"id":"PSY-FE-012","title":"微表情识别指标区间与「数据集内指标≠真实摄像头指标」","level":"B","summary":"实验室短片段上 3~5 类 UF1 约 0.35~0.63；一旦搬到长视频先定位后识别（最接近真实摄像头），MEGC2025 冠军总分仅 0.09——跨协议、跨被试泛化差是结构性问题。","content":"CASME II 5 类 LOSO 基线 LBP-TOP+SVM 63.41%；CAS(ME)³ 3 类 UF1 34.93~61.42%（STSTNet 37.95→点云 PointNet++ 61.42）；MEGC2025 ME-STR 冠军 STRS 0.09（识别 F1 0.645~0.667、spotting F1 0.067~0.118，测试集=10 条 SAMM 200fps + 20 条 CAS(ME)³ 30fps）；ME-VQA 冠军粗粒度 UF1 0.733/细粒度 0.368；","rel":[]},{"id":"PSY-FE-013","title":"端侧运行时选型与字节预算事实","level":"B","summary":"浏览器时序模型三运行时里 ONNX Runtime Web 与本仓 ESM 桥形态最合；任何新模型文件必须登记进 size_budget（vendor/mediapipe 惰性预算 14,000,000B，实测 13,674,721B），未登记即判红。","content":"npm unpacked（2026-10-11 实查）：@tensorflow/tfjs 4.22.0=147,474,474B；onnxruntime-web 1.30.0=144,618,540B（含多后端 wasm 变体，浏览器实取子集，单 wasm simd ~10MB 级）；@huggingface/transformers 4.3.1=9,962,435B（底层即 ORT-web，v3 起带 WebGPU）。WebGPU：Chrome 113（2023-05）/Firefox 141 Windows（2025-07）/Safari 26（2025）全线可用，只作加速不作依赖。","rel":[]},{"id":"PSY-FE-014","title":"微表情自动化识别的学术现状与浏览器端空白","level":"B","summary":"学术上微表情识别远未解决（综合基准 UAR≈40%，长视频 spotting 假阳性高），浏览器端没有任何现成微表情专用模型——「端侧微表情识别」目前不存在可复用方案。","content":"三个证据面：① 学术前沿——MEGC2025（ACM Multimedia 官方微表情挑战赛，第 8 届，megc2025.github.io）报告：长视频 Spot-then-Recognize（先从长视频里找出微表情再识别类别）任务假阳性高，仍是公认难题；近期视觉-语言方法 MECLIP 在综合基准上 UAR（不加权平均召回率）约 39.6%、UF1 约 40.0%，说明「认出微表情是哪种情绪」的学术天花板本身就低。② 浏览器生态——ONNX Runtime Web（微软开源的浏览器推理引擎，onnxruntime.ai）官方 demo 有实时普通表情检测，但没有任何微表情专用模型；","rel":[]},{"id":"PSY-MM-001","title":"多模态融合共识与面部证据的产品定位边界","level":"B","summary":"多模态融合有增益但不大（85% 系统更优、绝对约 +4.6pp）；面部证据权重应低于文本语义+语用，输出带不确定性话术、摄像头默认关闭。","content":"情感计算领域由 Picard 1997《Affective Computing》（MIT Press）奠基（定义为「与情绪相关、源于情绪或刻意影响情绪的计算」），本身是面部心理学与语义理解两大领域的交叉学科名。融合共识：D'Mello & Kory 2015（ACM Computing Surveys 47(3):43，90 个多模态系统的元分析）多模态在 85% 的系统上胜过最佳单模态，绝对提升约 4.6 个百分点（相对约 12.7%）；声音+面部是最常用组合——融合有增益但不大，任何单一模态都不是判官。","rel":[]},{"id":"PSY-MM-002","title":"面部证据的产品定位：作探询线索，不作裁决依据","level":"D","summary":"表情证据在心屿只有三种合法输出：如实标注、温柔探询、可视化染色；不裁决文本判定、不触碰危机逻辑、不断言用户动机——这是面部证据效度边界（Barrett 2019）直接导出的产品规则。","content":"原策划槽位（2026-10-11 索引.md），由本维度研究员实研后落条。该原则由效度争议导出：面部动作不是情绪的可靠普适指标（Barrett 等 2019 PSPI 综述，20(1):1-68，被引约 2700，https://pmc.ncbi.nlm.nih.gov/articles/PMC6640856）；微表情作为意图/谎言证据不足（[[PSY-FE-006]]）；Duchenne 真笑标记在感知层有效但作「真心指标」有强度伪影争议（[[PSY-FE-005]]）。翻译成产品规则三条：①表情读数只允许三种输出——界面标注（含「读数不稳」出口）、提示词探询指令、星雾染色；","rel":[]},{"id":"PSY-MM-003","title":"多模态融合两式：特征级早融合 vs 决策级晚融合——心屿走晚融合","level":"B","summary":"多模态融合分特征级早融合与决策级晚融合两类；心屿选晚融合（文本双路裁决、表情作证），因可解释、零训练、可断言，且表情侧标定样本远弱于文本侧。","content":"多模态融合有两类基本做法：①早融合/特征级——把各模态特征向量拼在一起喂一个模型，效果好但需要训练数据与训练过程，且不可解释；②晚融合/决策级——各模态独立判定后按规则合并，可解释、零训练、可逐字回归测试。ERC 综述（Fu 等 2023，Electronics 12(22):4714）将融合方法列为对话情绪识别的三大组织维度之一。心屿选晚融合：文本双路（词典+LLM）握裁决权，表情作证者。","rel":[]},{"id":"PSY-MM-004","title":"证据文本化注入 LLM 提示词：ERC 的轻量主流路线（2024-2026）","level":"B","summary":"把表情读数文本化后注入 LLM 提示词（textualized multimodal priors）是 2024-2026 对话情绪识别的轻量主流路线，也是零构建静态前端唯一零新组件的多模态路径；向量级对齐等引入本地模型时再做。","content":"让 LLM 理解非文本模态，不一定需要多模态大模型：把其他模态的识别结论写成结构化文字塞进提示词，是 2024-2026 对话情绪识别（ERC）方向反复出现的轻量路线——2026 年 ScienceDirect 一文明确称其为「textualized multimodal priors」（文本化多模态先验）；2025 年 PMC 收录论文用提示学习融合文本与音频特征。对比路线：Emotion-LLaMA 等走情绪专用编码器（音频/视觉/文本分别过 encoder 再融合），在 MER2023 等基准上表现强，但需要训练与算力。","rel":[]},{"id":"PSY-MM-005","title":"端侧面部推理的算力现实（WASM/GPU 基准与本项目实测）","level":"B","summary":"MediaPipe FaceLandmarker（478 点 + 52 维 blendshape）在普通浏览器可实时跑（WASM SIMD 9.13MB 或 WebGL，GPU/CPU 双路），普通笔记本余量大——但该余量属于宏观表情，跑不动微表情要求的 ≥30fps+时序模型。","content":"硬数据：① 体积——MediaPipe FaceLandmarker 端侧包 = face_landmarker.task 3,758,596B（3.59MB）+ vision_wasm_internal.wasm 9,574,032B（9.13MB）+ 两个胶水 JS ≈13.4MB（本仓 src/vendor/mediapipe/ 字节实测），可惰性加载。② 速度——Chrome 团队 2024-05 实测：Apple M1 上该任务的 WASM-CPU 与 WebGL-GPU 推理耗时大致相当；社区报告视频模式约 20~60fps（无统一官方基准表，仅作区间参考）。","rel":[]},{"id":"PSY-MM-006","title":"面部证据只标注不裁决：本仓三路仲裁规则","level":"B","summary":"本仓三路仲裁规则：文本双路裁决（危机短路→LLM 采信→词典兜底），表情只标注不裁决、分歧如实展示、crisis 恒 false、margin<0.15 出『读数不稳』。","content":"已落地规则（2026-10-11 实读核对）：①词典快判→危机短路最高优先（chat-agent.js:218），危机词不因网络延迟；②LLM 精判（temp=0/6s 超时）一致或分歧均采信 LLM，LLM 败则词典兜底（chat-agent.js:219-225）；③后端 /api/emotion 可用即以后端为准，消除 JS/Java 双真相（chat-agent.js:244-246）；","rel":[]},{"id":"PSY-MM-010","title":"多模态融合三式（早期/晚期/注意力）与本仓推荐","level":"B","summary":"三种融合架构中，MER2024 官方基线实证注意力融合多模态（79.31 WAF）优于最佳单模态（73.02）；心屿当前阶段的正确落点是晚期决策级（表情第三路只标注），数据充足后再升注意力对齐。","content":"MER2024 基线：各模态投影共享维度后以 softmax 注意力加权融合；A+V+T 多模态 79.31 WAF vs 最佳单模态 HUBERT-large 73.02；原文明言有限标注数据下复杂结构会过拟合。早期特征级未取得一手对比数字（不硬编）。本仓现状与推荐：词典+LLM 分歧采信 LLM（chat-agent.js:216-227）、表情第三路只标注不裁决（:250-256）=决策级形态；升注意力前先过两道门——自采 500+ 轮数据与 face confidence≥0.15 置信门（rules:191）；语义对齐先走零成本 family 折叠（rules:27-30，8 类对齐文本 6 类）。","rel":[]},{"id":"PSY-AP-012","title":"从语言推断自杀风险：NLP 基准性能与真实部署边界的两方证据","level":"D","summary":"语言信号能被模型学到（基准 AUC 0.8–0.9），但自杀基率太低使 PPV≤0.01、部署伦理争议未决——陪伴 AI 只做检出转介，不做风险评分。","content":"危机词、告别语句、绝望表达——语言是自杀风险最直接的外显信号，「用 NLP 从语言识别风险」因此是自杀预防最热的方向之一。但证据现状是「基准强、部署弱」的两张皮，产品若只看基准数字就会走错路。","rel":[]},{"id":"PSY-AP-013","title":"守门人训练（QPR 等）对识别与转介的效果：证据与批评两方","level":"D","summary":"守门人训练稳定提升知识与自我效能（g≈0.7），但行为效应不显著、态度多回基线——识别与转介须系统内建，不能只指望培训人。","content":"「守门人」（gatekeeper）= 被培训来识别自杀信号并转介的普通人（教师、宿管、同事）；QPR（Question, Persuade, Refer）是覆盖面最广的商业课程。证据是典型的「近端有效、远端存疑」。","rel":[]},{"id":"PSY-AP-014","title":"危机热线与文字热线的即刻效果：大样本感知结局与渠道结构（2022-2026）","level":"B","summary":"危机热线/文字热线即刻效果有实证：自杀来电者 98% 觉得有帮助、文字者 46.1% 轻生念头减轻——但全是自报，5.1% 反而更糟。","content":"危机热线/文字热线是转介的「终点站」，其即刻效果在 2020s 有了大样本实证（美国 988 Lifeline 电话线与文字伙伴 Crisis Text Line）。","rel":[]},{"id":"PSY-AP-015","title":"陪伴 AI 产品红线：不做风险评估，只做温暖转介","level":"A","summary":"陪伴 AI 检出危机信号只做「接住+温暖转介」，永不输出风险等级或评估结论——现有聊天体危机应答 0% 合格，评估交给人。","content":"红线三句：①不评估——不输出「你是高风险/低风险」，不打风险分，不做自伤/自杀可能性判断；②短路——检出危机信号即跳过正常生成链路（LLM 也不调），走固定安全话术；③温暖转介——陪伴语句接住情绪 + 给具体可拨热线 + 回抛联结问题（「身边有可以叫一声的人吗」），不是甩号码列表。","rel":[]},{"id":"PSY-ER-001","title":"Gross 情绪调节过程模型：情绪生成时间轴上的五个调节入口","level":"A","summary":"情绪沿「情境→注意→评估→反应」时间轴生成，调节有五个入口；换解读（认知改变）通常优于事后硬压反应，注意类整体无效、分心例外（效应量见 [[PSY-ER-002]]）。","content":"Gross 的过程模型是情绪调节领域引用最多的框架：情绪不是瞬间爆发的，而是沿「情境 → 注意 → 评估 → 反应」的顺序生成，调节可以在五个点上介入——①情境选择（提前选择或避开某些人/场景）、②情境修正（当场改变场景）、③注意部署（分心、专注）、④认知改变（换一种解读，重评属于这里）、⑤反应调节（情绪已经起来后直接压反应：抑制表情、深呼吸、运动）。前四个是「情绪点燃前」的前因端干预，第五个是「情绪点燃后」的反应端干预。","rel":[]},{"id":"PSY-ER-002","title":"认知重评 vs 表达抑制：两条元分析路线的实证差异与「策略内部」真相","level":"A","summary":"实验元分析：重评事件 d+=0.36 优于重评自身反应 0.23，而「压感受/别想了」对主观体验无效（-0.04/-0.12）——教换解读，不教硬憋。","content":"两条独立元分析路线 + 原始问卷研究，结论同向：认知重评总体优于抑制，但真正关键的差异在「策略内部」。实验线（Webb, Miles & Sheeran 2012, Psychological Bulletin 138(4):775-808，PMID 22582737）：306 组实验比较按过程模型归类。过程层面：认知改变 d+=0.36（小到中）、反应调节 d+=0.16、注意部署 d+=0.00（整体无效应）。拆开看更有用：重评「事件本身」（换个角度解读发生了什么）d+=0.36，重评「自己的反应」（劝自己别紧张）d+=0.23，换位思考 d+=0.45，分心 d+=0.27，专注 d+=-0.26。","rel":["fear"]},{"id":"PSY-ER-003","title":"抑制并非普适有害：文化与情境的对立证据（争议条目）","level":"D","summary":"抑制的害处有文化与情境边界：负面关联只在美籍样本出现、香港华人样本不出现，灵活切换者适应最好——禁输出「别憋着」类普适命令。","content":"「抑制总是有害」在科普里常被写成定论，但一手证据并不支持这个普适说法——这是学界真实的分歧点，两方都要看。一方（抑制与负面结局稳定相关）：Gross & John (2003) 五个研究发现习惯性抑制者正性情绪少、负性情绪多、人际功能与幸福感更差；Aldao 等 (2010) 元分析中抑制与四类精神病理症状呈中到大相关；Webb 等 (2012) 显示抑制内心体验（d+=-0.04）与压制想法（d+=-0.12）对主观感受无效。","rel":[]},{"id":"PSY-ER-004","title":"调节灵活性：情境敏感 + 策略库 + 反馈响应（Bonanno 框架与 2024-2026 前沿）","level":"B","summary":"适应良好的核心是灵活性三组件：读懂情境、手握多策略、依反馈调整——产品可直接映射为「策略菜单+情境匹配+用后回访」闭环。","content":"Bonanno 学派对「哪种策略最好」换了个问法：好不好不看策略，看策略和情境配不配。框架（Bonanno & Burton 2013, Perspectives on Psychological Science 8(6):591-612，PMID 26173226，DOI 10.1177/1745691613504116）：批评学界默认「某策略一律好/一律坏」的「一律有效谬误」（fallacy of uniform efficacy），提出调节灵活性三组件——①情境敏感性（sensitivity to context）：读得懂此刻情境的要求；②策略库（repertoire）：手里有多个可换用的策略；","rel":[]},{"id":"PSY-ER-005","title":"Neff 自我同情三组件与 SCS 量表：构念、测量与未决的量表之争","level":"A","summary":"「对自己太苛刻」的对症构念是自我同情：自我善待+共通人性+正念三组件，SCS 26 题官方量表有中文版；三组件定义是共识，量表总分之争未决。","content":"自我同情（self-compassion）是「对自己太苛刻」这类困扰的正面对症构念，由 Neff 提出：受苦时①自我善待（self-kindness，像对好朋友那样对自己说话，而不是自我攻击）、②共通人性（common humanity，认识到痛苦与不完美是所有人共享的处境，而不是「只有我这么惨」的孤立感）、③正念（mindfulness，平衡地觉察痛苦——既不压抑回避，也不夸大沉溺）。三组件各有对立面：自我善待 vs 自我评判、共通人性 vs 孤立、正念 vs 过度认同——即自我同情同时是「降低对自己苛刻」的六面体。","rel":[]},{"id":"PSY-ER-006","title":"自我同情 vs 自尊：不靠社会比较、不随成败起落的稳定自我价值感","level":"B","summary":"自我同情和自尊一样关联幸福感，但不靠社会比较、不随成败起落、与自恋脱钩，还提升改进动机——夸自尊不如教善待。","content":"「先教会用户接纳自己，还是先夸用户很棒？」——实证答案指向自我同情而不是自尊灌水。Neff & Vonk (2009, Journal of Personality 77(1):23-50, DOI 10.1111/j.1467-6494.2008.00537.x, PMID 19076996，Europe PMC 摘要已读) 两研究：Study 1（N=2,187）发现自我同情预测更稳定的自我价值感（不随具体成败起落），且与社会比较、公众自我意识、自我反刍、愤怒、认知闭合需求的负关联强于自尊；关键是「自尊（而非自我同情）与自恋正相关」。","rel":["anger"]},{"id":"PSY-ER-007","title":"自我同情与焦虑抑郁：相关元分析与 RCT 元分析的证据链及边界","level":"A","summary":"相关元分析 r=-0.54；RCT 元分析：抑郁 0.44/焦虑 0.36/压力 0.43 短期有效，线上形式更小、焦虑随访不显著——话术有效但别夸大。","content":"自我同情与焦虑抑郁的关系有两条独立证据线，结论同向但都要带边界条件。","rel":["fear"]},{"id":"PSY-ER-008","title":"自我批评的后果与自我关怀式回应（含 Gilbert CFT 概述）","level":"B","summary":"自我批评预测 4 年后抑郁与功能受损，机制是推开身边人；自我关怀式回应能降自我批评（g≈0.51）——先接住，再教善待。","content":"「对自己太苛刻」不只是难受，它会往前走。前瞻证据：Dunkley 等 (2009, Comprehensive Psychiatry 50(4):335-346，2008 年在线；PMC 全文已读) 对 107 名临床患者追踪 4 年——控制基线症状与神经质后，自我批评（DAS）仍独特预测 4 年后的抑郁症状、访谈评定的重性抑郁发作与全面心理社会功能受损；三波中介模型显示，这条链路经由「负性社会互动增多＋感知社会支持下降」完全中介。大白话：自我批评伤人的机制之一是把身边人推开、并且让自己觉得「没人撑我」——与 [[PSY-AT-003]] 的「感知支持才是保护源」直接互证。注意：前瞻相关非因果定论。","rel":[]},{"id":"PSY-EM-001","title":"共情的多维结构：认知共情、情感共情、共情关怀——Davis 人际反应指针量表（IRI）","level":"A","summary":"共情不是单一能力而是多维构念：认知共情（观点采择）、情感共情（情感共鸣）、共情关怀（利他导向的关切与助人动机）；IRI 28 题四分量表是通行测量。","content":"主流共识把「共情」拆成多个可分开测量的成分，不是一个笼统的「有同理心」。Cuff 等人（2016）对共情文献做了系统梳理，从 43 种独立定义里归纳出 8 个反复出现的主题（认知还是情感？一致还是不一致？自动还是可控？……），结论是共情必须按多维构念来定义和使用——单一定义已经对研究和实践造成负面影响。通行测量工具是 Davis 的人际反应指针量表（IRI）：28 题自评、四个分量表各 7 题。观点采择 PT（自发采纳他人视角，认知维度）、想象 FS（代入虚构角色，认知维度）、共情关怀 EC（对不幸者感到温暖/同情/关切，情感维度-他人导向）、个人痛苦 PD（因他人痛苦而自身感到不安，情感维度-自我导向）。","rel":[]},{"id":"PSY-EM-002","title":"共情准确性 ≠ 感知共情：一条「推断轨道」，一条「感受轨道」","level":"B","summary":"共情准确性=「推断准不准」（对他人情绪想法的正确率），感知共情=「对方感到被理解」；两条轨道可分离，产品要分别测，不能拿一条冒充另一条。","content":"共情准确性（empathic accuracy）指一个人正确推断他人当时想法和感受的程度。Levenson 与 Ruef（1992）把它操作化：31 名被试观看 15 分钟婚姻互动录像、用转盘实时评定指定配偶的情绪，再与配偶本人的自评比对算准确率；结果对负性情绪的评定准确率在「观察者与目标生理反应联动高」时最高，而正性情绪的觉察与观察者自身低心血管唤醒有关、与联动无关。Ickes（1993）在 Journal of Personality 提出 empathic accuracy 术语与标准化研究范式，成为这条研究线的起点。","rel":[]},{"id":"PSY-EM-003","title":"LLM 共情表达的实证（2023-2026）：第三方盲评中 AI 回复普遍「更共情」","level":"B","summary":"2023-2026 多项盲评实证：LLM 共情回复在第三方评价中得分高于人类（含受训危机热线员）；但其边界是「被评的文本」，不是「被长期陪伴的人」。","content":"最早也是传播最广的一项：Ayers 等人（2023, JAMA Internal Medicine）抽取 Reddit r/AskDocs 的 195 个「患者提问+认证医生回答」，让 ChatGPT（GPT-3.5）重新作答，由持证医疗专业人员盲评，共 585 次评估：ChatGPT 回复被偏好 78.6%（95% CI 75.0%–81.8%）；被评为「good/very good 质量」的 78.5% vs 医生 22.1%（约 3.6 倍）；被评为「empathetic/very empathetic」的 45.1% vs 医生 4.6%（约 9.8 倍）；平均共情分 3.65 vs 2.15。","rel":[]},{"id":"PSY-EM-004","title":"「AI 共情」的争议面：真实性之争、披露效应与「AI 共情选择悖论」","level":"D","summary":"AI 共情「好用但不被信任」：盲评得分更高是实，披露的短期代价证据不一致（作者标注有损、回应者透明未见损），多数人仍选人类共情；「模拟共情是否为真共情」是未决之争。","content":"批评方（原则上不可能，甚至有害）：Montemayor、Halpern 与 Fairweather（2021, AI & Society）主张共情是 AI 的「原则性极限」而非技术问题——原话「empathic AI is impossible, immoral, or both」；因为共情建立在第一人称的情感体验之上（「想象处于他人具体处境中是什么感受」），而机器没有可借以想象的情感体验。","rel":[]},{"id":"PSY-AT-001","title":"成人依恋理论：内部工作模型与「类型 vs 维度」两种范式","level":"A","summary":"依恋是终身起作用的关系操作系统：内部工作模型由早年经验成形、可被新关系部分改写；「安全/焦虑/回避」是维度不是人格标签——产品可按焦虑/回避两维度设计读数（若做，须先验证从对话文本推断的可行性与效度）。","content":"内部工作模型是什么：Bowlby（1969/1982）提出，婴儿会根据照料经历形成「内部工作模型」——对「我自己值不值得被回应」和「别人可不可靠」的心理表征，包含期望、信念和「行为规则/脚本」（原文：individuals develop 'internal working models' of attachment that describe the relationship between the infant's self and his attachment figure）。它像一副有色眼镜：人会用旧模型预期新关系，也会挑选与之一致的关系经验。","rel":["fear"]},{"id":"PSY-AT-002","title":"孤独感：Cacioppo 进化模型（再联结信号）与 Holt-Lunstad 健康效应元分析","level":"A","summary":"孤独=「感知到的联结不足」而非独居本身；它是像饥渴一样的再联结信号，长期不解除会经威胁警觉→自我实现闭环伤身——产品要接住信号，更要推回真实联结。","content":"孤独是主观感知，不是客观数量：Hawkley & Cacioppo (2010) 原文定义——「孤独与感知到的社会隔离同义，而非客观隔离」，是「感到自己的社交需要没被关系的数量、尤其质量满足」的痛苦感受。可以独居而不孤独，也可以天天社交却孤独；通行测量是 UCLA 孤独量表。患病率：约 80% 的 18 岁以下者、40% 的 65 岁以上者至少偶尔孤独；15%–30% 的人处于慢性孤独。","rel":[]},{"id":"PSY-AT-003","title":"社会支持缓冲假说：保护有条件，且「被看见的帮助」可能帮倒忙","level":"B","summary":"支持的保护主要来自「需要时有人可用」的感知，而非人越多越好；显性帮助有时帮倒忙——产品宜做可用的陪伴，不做表演式救助。","content":"两种模型：Cohen & Wills (1985, Psychological Bulletin 98(2):310-357) 的经典区分——「缓冲模型」说支持只在压力情境下起保护作用（压力×支持的交互项）；「主效应模型」说支持无论有无压力都直接有益。他们评审的结论是：两者都存在，但取决于支持怎么测——缓冲证据出现在「感知到的人际资源可用性」（perceived availability，功能性测量）上；结构性测量（社交网络规模、婚姻状况等）多表现为主效应。一句话：**「我需要时有人可用」的感觉才是抗压力的关键，不是人越多越好。","rel":[]},{"id":"PSY-AT-004","title":"人-AI 陪伴关系（2024-2026）：缓解孤独与依赖风险并存，边界话术必须先行","level":"D","summary":"2024-2026 证据两极：AI 陪伴短期确能缓解孤独，但重度使用与更高孤独/依赖相连——产品须把 AI 定位为练习场与陪跑，明确不替代真人联结。","content":"缓解面（真实存在，别否认）：de Freitas, Oğuz-Uğuralp, Uğuralp & Puntoni（HBS 工作论文 24-078，后刊 Journal of Consumer Research）的多项实验显示：与 AI 伴侣聊天机器人互动能显著降低当下孤独感，效果优于通用 AI 助手和低响应聊天机器人（回应性是关键），自我表露是核心机制，约一周稳定使用后孤独下降可持续。","rel":[]},{"id":"PSY-AT-005","title":"ELIZA 效应：用户向对话程序投射理解与情感的倾向，LLM 时代被放大","level":"B","summary":"人会把模式匹配的回复读成「被理解」——1966 年 ELIZA 如此，LLM 更甚；产品须显式自认 AI 身份、不假装理解，把投射用在诚实的陪伴上。","content":"起源：Weizenbaum (1966) 在 Communications of the ACM 9(1):36-45 发表的 ELIZA，其 DOCTOR 脚本让用户把它当成心理治疗师倾诉。最著名的轶事出自他 1976 年的书：他自认为深知 ELIZA 只是程序的秘书，也要求他离开房间、让她与 ELIZA「私聊」。⚠️ 经典时代的证据是作者的个人观察与轶事，不是系统实证——但这个效应本身后来被大量现代研究证实。","rel":[]},{"id":"PSY-DC-001","title":"Rogers 三条件（真诚一致／无条件积极关注／共情理解）：原著论断与后续元分析实证","level":"A","summary":"共情理解（r=.28）、积极关注（g=.28）、真诚一致（r=.23）与疗效稳健相关，但「必要且充分」论断被批评——AI 陪伴取三条件为回复姿态，不作疗效承诺。","content":"Rogers 在 1957 年原文提出治疗师三条件：真诚一致（表里如一）、无条件积极关注（不评判地接纳）、共情理解（进入对方内在参照框架），并主张三者对建设性人格改变「必要且充分」。后续实证（APA 关系要素系列，顶刊 Psychotherapy）：共情与结局加权 r=.28（95%CI .23–.33，约 d=.58；82 个独立样本、6,138 名来访者），且来访者与观察者评的共情比治疗师自评更预测结局（Elliott 等 2018）；积极关注合并 g=.28、多层模型下 g=0.36（k=64；Farber, Suzuki & Lynch 2018），2011 版为 r=.27（CI .16–.38；","rel":[]},{"id":"PSY-DC-002","title":"倾听反映与 OARS：动机式访谈微技术与「别迷信公式」的证据","level":"B","summary":"OARS=开放式问句/肯定/反映/小结，反映是 MI 表达共情的基础技能；但反映:提问比例与结局无显著相关——学技术别迷信公式，说教与更差结局相关。","content":"OARS 四件套（Miller & Rollnick 2013 教科书 + MI 官方站定义）：开放式问句（引出对方的经历、视角、想法）、肯定（对优点、努力、过往成功给予肯定以建立信心）、反映（官方表述「MI 的基础技能，也是我们表达共情的方式」）、小结（确保双方理解一致、强化对方说过的关键点）。官方站同时警告 MI 要求从业者「克制不请自来的建议、对抗、指示、警告」——教科书里这叫 righting reflex（抢着修好的冲动）。MI 整体疗效：Lundahl 等（2010，119 项研究 meta）对弱对照合并 g=0.28（小而稳定），对特定活性治疗 g=0.09 不显著。","rel":[]},{"id":"PSY-DC-003","title":"情绪确认（validation）：DBT 六层次与「降低情绪唤醒」实证的真实形状","level":"B","summary":"情绪确认=告诉对方「你的反应有道理」，DBT 分六层次操作化；实验支持确认降愤怒/羞耻时心率、无效化升唤醒，但效应有情绪特异性，勿写成「确认=万能降温」。","content":"确认（validation）指传达「你的反应在你的生活背景下说得通、可被理解」（Linehan 框架）。DBT 把它操作化为六个层次（Linehan, 1993）：①无偏地、在场地倾听；②准确反映；③说出对方未言明的感受；④用过去学习史/生物学原因确认；⑤用当下情境确认（正常化：换谁都会这样）；⑥彻底真诚（不端着的真实回应）。实证形状（两个独立实验室研究，方向一致但不一刀切）：Shenk & Fruzzetti（2011，大学生数学应激范式）发现无效化反馈组负性情绪、心率、皮电显著上升，确认组心率显著下降、皮电升幅更小、负性情绪无显著变化——被 Kuo 等概括为「无效化升级情绪，确认降低或不影响情绪」。","rel":["anger"]},{"id":"PSY-DC-004","title":"支持性对话中自我表露的边界：何时帮助、何时有害与 AI 陪伴的默认规则","level":"B","summary":"治疗师自我表露在「合拍、简短、以对方为中心」时有益（相似性表露最受欢迎），失谐冗长有害；AI 陪伴默认零自我表露，不虚构第一人称经历。","content":"有益面：Henretty, Currier, Berman & Levitt（2014，53 项实验/准实验 meta）发现帮助者自我表露总体让来访者评价更积极、更愿意向其继续表露；最受欢迎的表露类型是「揭示双方相似性」与「经验之谈」（尤其关于治疗之外的经历）；相似性表露还提高「愿意再来」。Hill, Knox & Pinto-Coelho（2018，21 项研究定性 meta）发现表露后最常见的后续过程是关系增强、功能改善、领悟增长、整体有帮助。","rel":[]},{"id":"PSY-DC-005","title":"心理抗拒（reactance）：Brehm 1966 原论断与「建议如何触发抗拒」的实证","level":"A","summary":"心理抗拒=自由被威胁时想恢复自由的动机；「必须/应该」式语言实测抬升愤怒（r=.21）与抗拒（r=.20）并削弱说服——给建议先承认对方有选择权。","content":"Brehm（1966，Academic Press 原著）的原论断：当人感到自己的自由行为被威胁或被消除时，会产生一种令人不适的动机唤起——心理抗拒（reactance），它驱动人去恢复失去的自由；被强推的选项反而显得更有吸引力。Steindl 等（2015）综述开篇即引原书卷首语「为什么孩子有时偏要反着做？」，并把抗拒定义为「自由被威胁或丧失时出现的不适动机唤起，是恢复自由的动机」。","rel":["anger"]},{"id":"PSY-DC-006","title":"自主支持 vs 控制型回应：自决理论（SDT）的元分析证据与可训练的自主支持行为","level":"A","summary":"自主支持=给选择、给理由、承认感受、用非控制语言；184 个数据集的元分析显示它与需要满足、自主动机和更好健康结果相连，控制型情境相反。","content":"自决理论（SDT，Deci & Ryan）的核心论断：人有三种基本心理需要——自主（行为出于自己的意愿而非被逼）、胜任、关联；满足这三种需要的环境促进健康发展与功能（Ryan & Deci 2000；SDT 官方站本轮实取，官方表述即研究「控制型 vs 自主支持型环境」如何影响功能、健康、表现与坚持）。","rel":[]},{"id":"PSY-DC-007","title":"未被寻求的建议与「先共情后解决」：动机归因、响应性支持与匹配边界","level":"B","summary":"未被寻求的建议易被归因为建议者自利、降低采纳与学习；先响应感受再谈行动——过多实用建议反而降低「被听见」感。","content":"建议的社会规范面：Goldsmith & Fitch（1997，Human Communication Research 23(4):454-476，被引口径 OpenAlex 393 / S2 396）把建议当作社会支持中受规范约束的行为——人们对「什么时候该给建议、谁有资格给」有一套隐性规范；不合规范的建议（未被寻求、时机不对、越位）带来面子威胁与关系代价。这是「先共情后解决」的规范基础。","rel":[]},{"id":"PSY-DC-008","title":"产品落点：纯倾诉轮不注入知识、不抢着给建议——设计依据、证据现状与自我校准","level":"C","summary":"有 2026 preprint（合成求助者被试）研究显示四大 LLM 共病「说多于听、情境未探明就急着解决」——纯倾诉轮不注入知识、不抢着给建议；建议须经请求许可后给。","content":"规则（设计推断，供提示词注入）：用户处于纯倾诉状态（未提问、未求建议、情绪在场）时，回复默认不注入心理学知识、不主动给建议；建议仅在用户明示需要或处境明确可控时经请求许可给出（「需不需要我帮你想几个办法？」）；知识类内容只走独立场景（用户主动提问、情绪教育卡），不进倾诉回复。","rel":[]},{"id":"PSY-MO-001","title":"情绪惯性 emotional inertia：情绪被上一刻拖着走，高惯性预示日后抑郁风险","level":"A","summary":"情绪惯性=情绪被上一刻拖着走的程度；高惯性者情绪难随情境转换，前瞻研究显示预示日后抑郁风险——读曲线要看趋势与个体基线，单点读数不算数。","content":"情绪惯性（emotional inertia）指情绪状态对改变的抵抗程度，用时间序列自相关衡量：这一刻的情绪有多大比例被上一刻预测。惯性高＝情绪「被拖着走」、难随情境切换——不管拖着它的是坏心情还是好心情。原始定义句：Emotional inertia refers to the degree to which emotional states are resistant to change（Kuppens et al., 2010）。","rel":[]},{"id":"PSY-MO-002","title":"情绪变异性与「过度平稳也异常」：两面证据与一个表面矛盾","level":"A","summary":"波动既非敌人也非目标：高不稳定与低幸福感共存，而抑郁者情绪反应反而钝化——太平与太乱都值得留意，健康曲线随事件起伏且事后能回落。","content":"先分清三个指标：变异性（标准差，波动幅度）、不稳定性（相邻时刻变化量）、惯性（自相关，见 [[PSY-MO-001]]）。元分析（79 篇文章、793 个效应量、N=11,381）：心理健康差与「更波动（ρ̂=-.178）、更不稳定（ρ̂=-.205）、更惯性（ρ̂=-.151）」共存，负性情绪上的关联更强（Psychological Bulletin 2015）。","rel":[]},{"id":"PSY-MO-003","title":"心情一致性记忆与判断：此刻的心情给同色调记忆与评价染色","level":"B","summary":"此刻心情给同色调记忆与判断染色：悲伤时更易想起坏事先例、评价更悲观——负性总结部分是心情伪影，先接情绪再陪看事实。","content":"理论起源：Bower (1981) 联想网络模型——情绪如同记忆网络中的激活节点，与当下心情同色调的材料编码更深、提取线索更多，此为心境一致性效应（mood-congruent memory）的经典解释框架（American Psychologist 36(2):129-148，被引 4,100+）；2022 年 Psychological Review 综述仍以联想网络/扩散激活模型为基线框架之一。","rel":["sadness"]},{"id":"PSY-MO-004","title":"情绪恢复动力学：平复需要时间，反刍会拉长恢复","level":"B","summary":"平复需要时间：27 种情绪里悲伤最持久，反刍拉长情绪持续时间；压力后负性情绪迟迟不消与十年后更差健康相关——允许慢慢好，别催快好。","content":"定义：情绪恢复＝诱发事件结束后情绪反应回落的程度，与「反应性」（事件中升多高）是两个可分离的指标（Journal of Affective Disorders 2011 以该区分设计双相与健康对照研究）。","rel":["sadness"]},{"id":"PSY-SH-001","title":"Tangney 自我意识情绪框架：羞耻 vs 内疚的行为差异（躲藏/攻击 vs 修复/道歉）","level":"A","summary":"羞耻=「我这个人不好」的整我评价，驱动躲藏/回避/攻击；内疚=「我这次做错了」的行为评价，驱动道歉/修复——先判用户在哪种状态再定回应方向。","content":"羞耻（shame）与内疚（guilt）日常口语常混用，但实证上是两条相反的行为通路。Tangney 2007 年《Annual Review of Psychology》综述（被引 3000+）梳理五大领域证据：①动机——羞耻对应「否认、躲藏、逃离」当下情境，内疚对应「弥补（amending）」；②共情——内疚倾向与他人取向的共情稳定正相关，羞耻反而破坏共情联结；","rel":[]},{"id":"PSY-SH-002","title":"羞耻与隐藏秘密：负担在「心头盘旋」而非「隐瞒动作」，倾诉有门槛","level":"B","summary":"秘密的负担在心头盘旋而非隐瞒动作：羞耻型秘密更盘踞；倾诉靠社会支持与应对效能减负——不逼问、等用户开口，开口后先给支持。","content":"秘密研究的核心发现颠覆直觉：秘密的负担不在「说谎/瞒住」的那一刻，而在一个人的时候——思绪会不受控地飘回秘密上去。Slepian 等人 2017 年在 JPSP 分析了 13,000+ 个秘密，摘要原句：人们自发想起秘密的频率，远高于遇到需要主动隐瞒的社交情境（\"people catch themselves spontaneously thinking about their secrets far more frequently than they encounter social situations that require active concealment\"）；且独立于隐瞒频率，思绪游离回秘密的频率预测更低的幸福感。","rel":[]},{"id":"PSY-SH-003","title":"羞耻的文化差异：文化模型派 vs 演化不变派（含中国样本证据，两方并陈）","level":"D","summary":"羞耻文化差异两方并陈：集体主义文化中羞耻或更建设性（文化模型派）；但羞耻-贬损架构跨文化不变、中国大学生羞耻照常预测自杀意念——底线按后者设计。","content":"羞耻的文化差异是活争议，两方都有硬证据，产品两条都不能只取其一。","rel":[]},{"id":"PSY-SH-004","title":"产品落点：去羞耻化回应原则（不逼问、正常化、把行为与人分开、先确认情绪）","level":"B","summary":"去羞耻化三原则：不逼问（等用户开口）、正常化（绝大多数人持有秘密——美国样本均值 13 个，中文话术用模糊量级）、把行为与人分开（羞耻态先确认再拆归因）——不构成治疗建议。","content":"本条目是 SH 域三条研究（[[PSY-SH-001]]/[[PSY-SH-002]]/[[PSY-SH-003]]）的产品端收敛。每条原则=一层实证底+一层设计映射，设计映射部分标明为库内导出（无直接 A/B 实验证据，上线前按产品流程验证）。","rel":[]},{"id":"PSY-AX-001","title":"状态-特质焦虑：Spielberger 框架、STAI 测量真相，与 GAD「担忧是言语性回避」假说","level":"A","summary":"焦虑要分两层看——「此刻多紧张」（状态）与「容易紧张的倾向」（特质），STAI 各 20 题分别测量；GAD 的担忧被 Borkovec 一派解释为「用言语把情绪压下去」的回避，有小样本实验支持但仍是假说。","content":"**状态 vs 特质（A 级）**：Spielberger 框架把焦虑拆成「现在感到的」与「一贯倾向的」。Julian (2011, Arthritis Care & Research 63(S11):S467-S472, PMC 全文实读)：STAI 共 40 题，S-Anxiety 与 T-Anxiety 各 20 题，4 点计分，约 10 分钟完成，已译 48 种语言；状态量表问「right now」的主观感受（apprehension/tension/nervousness/worry 与自主神经激活），特质量表测相对稳定的「焦虑倾向」（calmness/confidence/security）。","rel":["fear","calm"]},{"id":"PSY-AX-002","title":"担忧 vs 反刍：两种重复负性思维的区分与机制争议","level":"B","summary":"担忧指向未来、言语多、与焦虑相连；反刍指向过去、围着自我与症状转、与抑郁相连；两者高度重叠又能在实验室分开，机制解释（元认知 vs 建构水平 vs 反应风格）没有定论。","content":"**通俗区分**：担忧 = 「万一以后……」围绕未来威胁打转；反刍 = 「为什么我当时……」围着已发生的事、自己的感受与症状打转。两篇顶刊综述各自给出同向的结构：Watkins (2008, Psychological Bulletin 134(2):163-206)：重复思维（RT）的后果可建设性（创伤后恢复、适应性准备与预案、抑郁康复、健康行为）也可非建设性（抑郁、焦虑、身体健康问题），关键调节变量是内容效价、情境、以及抽象 vs 具体加工水平——RT 本身不分好坏，怎么想才分。","rel":["fear"]},{"id":"PSY-AX-003","title":"考试/表现焦虑与「倒U定律」：原典、现代批评与注意控制理论","level":"D","summary":"课本里「适度紧张发挥最好、过头就崩」的倒U曲线，原典研究的是小鼠习惯形成而非人类表现，学界早有系统批评；真正稳的硬数据是另一件事——考试焦虑损害表现（562 项研究元分析），且降低考试焦虑伴随成绩改善。","content":"**原典**：Yerkes & Dodson (1908) 论文题为「The relation of strength of stimulus to rapidity of habit-formation」，刊于 Journal of Comparative Neurology and Psychology 18(5):459-482（Crossref 题录核验）——题目本身说明它研究刺激强度与习惯形成速度的关系；今天流行的「唤醒/动机 vs 绩效倒U、任务越难最优点越低」是后世简化的传播版。","rel":["fear"]},{"id":"PSY-AX-004","title":"「别想太多/冷静点」：无效化回应与思想抑制反弹的证据","level":"B","summary":"「别想多了」一句话里藏着两个坑——不承认用户的情绪（无效化）+ 命令他不想（抑制），两条都有实验证据让状况更糟；但对「恐惧」的确认降唤醒效应弱于愤怒/羞耻，别把确认当万能降温键。","content":"**拆招**：「别想太多」「冷静点」「这有什么好担心的」「忍忍就过去了」= ①无效化（暗示用户的反应没道理）+ ②抑制指令（叫TA别想）。**无效化的实验形状**：数学应激范式后施加无效化反馈的大学生，负性情绪、心率、皮电显著上升；确认组心率显著下降、皮电升幅更小（Shenk & Fruzzetti 2011, J Soc Clin Psychol 30(2):163-183；结果转述经 Kuo et al. 2022 引述与库内 [[PSY-DC-003]] 核对）。","rel":["anger","fear"]},{"id":"PSY-AX-005","title":"焦虑的可循证自我调节：重评、放松、正念与慢呼吸——效应量与边界","level":"B","summary":"换个角度解读（重评）实验室效应量 d+≈0.36、放松训练元分析 d≈0.5–0.6、正念疗法对焦虑 g=0.63——但都付出「结构化干预」的代价；对身体感觉敏感的人，「扫描身体」式正念可能反而升焦虑。","content":"**重评**：Webb, Miles & Sheeran (2012, Psychological Bulletin 138(4):775-808)：306 组实验比较中认知改变 d+=0.36（小到中）、反应调节 0.16、注意部署 0.00；拆开看：重评事件本身 0.36、重评自己的反应 0.23、换位思考 0.45、分心 0.27、专注 -0.26；「抑制」不是一回事——抑制表情有效（d+=0.32）但抑制内心体验 d+=-0.04、压制事件想法 d+=-0.12（详见库内 [[PSY-ER-002]]）。含义：教用户「换个角度看这件事」有元分析背书，「别想了/忍住」没有。","rel":["fear","calm"]},{"id":"PSY-AX-006","title":"产品落点：陪伴 AI 面对 fear/不安情绪的回应纪律","level":"C","summary":"对 fear/不安，AI 的纪律是「先承认、再具体、后选项」：不否认危险、不空头保证、不抢着解决；其中禁说「别想太多/冷静点」有 B 级证据支撑，其余为结构外推，需产品 A/B 验证。","content":"**规则组（供提示词注入）**：①**禁无效化语**（证据最强，B 级，见 [[PSY-AX-004]]）：「别想太多」「冷静点」「有什么好怕的」。②**不否认危险也不放大**：「不会有事的」式空头保证禁用——保证落空侵蚀信任且进入安慰寻求循环；改为承认不确定 + 具体下一步。安慰寻求的代价有实证：Parsons et al. (2025, J Anxiety Disord 115:103057, n=62 OCD/58 对照)：人际安慰寻求短期缓解、「代价是制造挫败并绷紧关系」；Sun et al. (2025, BMC Geriatr 25(1):680, n=301 安置老人，横断面)：过度安慰寻求通过放大负信息注意加剧焦虑。","rel":["fear"]},{"id":"PSY-GR-001","title":"哀伤阶段模型的实证批评：不是阶梯，弹性才是最常见的轨迹","level":"A","summary":"哀伤不走「否认→愤怒→讨价还价→抑郁→接受」的固定阶梯——实证上「接受」从头到尾都是最高频项、最常见的整体轨迹是「稳得住」；产品禁用阶段叙事回应。","content":"【实证检验】Maciejewski 等（2007，JAMA）用耶鲁丧亲研究（康涅狄格 233 名丧亲者，2000-2003 入组，丧后 1-24 个月五次结构化评定，测 disbelief/yearning/anger/depression/acceptance 五项）做了阶段论最著名的直接检验。","rel":["anger"]},{"id":"PSY-GR-002","title":"持续性联结：从「放手」到「带着爱继续联结」，好处与边界并存","level":"D","summary":"现代哀伤观不要求「放下逝者」：与逝者保持联结是常态，安抚与痛苦两面常并存（2024 系统综述：保留 vs 放下孰好文献仍未确认）；「内化」式联结多半有益、「卡在未完成事务」的执念式联结更痛（华人团队纵向，待复制）；产品不劝放手，也不放任执念叙事。","content":"【两派立场】经典精神分析传统把哀伤定义为「撤回情感投注」的工作：Prigerson 等 2021 年原文复述 Freud 视哀悼为正常反应、\"the hard, often painful, work a mourner must do to withdraw emotional attachment to the deceased person\"，甚至认为医疗介入有害。「continuing bonds」一派（Klass, Silverman & Nickman 主编文集，Taylor & Francis；Crossref DOI 10.4324/9781315800790，三位编者题录可核，电子版 2014；","rel":[]},{"id":"PSY-GR-003","title":"延长哀伤障碍（PGD）：ICD-11 与 DSM-5-TR 双轨入册，边界之争未决","level":"B","summary":"重度、持久、致功能受损的哀伤现在有正式名字——ICD-11 约 6 个月、DSM-5-TR 12 个月起算，双轨入册；「这是不是把正常哀伤病化」的争议仍在，产品永不下诊断、只做温暖转介。","content":"【官方入册】ICD-11 新增 21 个精神疾病，PGD 是其中争议最大者之一（Reed 等 2022，World Psychiatry：这些新类别 \"has been the focus of considerable activity and/or controversy\"）。DSM-5-TR 方面：APA Assembly 于 2020-11-07 投票通过把 PGD 从 DSM-5「待研究」条目（PCBD）升为正式诊断（Prigerson 等 2021 全文，PMC 可核）。【两套标准差异】（Eisma 2023 Table 1 逐字对照，PMC 实读）DSM-5-TR：A 死亡距今 ≥12 个月（儿童青少年 ≥6 个月）；","rel":[]},{"id":"PSY-GR-004","title":"哀伤支持证据：什么话有害、什么帮忙——都有据可查","level":"C","summary":"「时间会治愈一切」式的话之所以伤人，是因为它把社会的时间表压在悲伤上——实证里任何强度的持续悲伤表达都让围观者想躲；真正有用的是「在场、说逝者的名字、让悲伤被见证、允许暂停」。","content":"【有害面】Wortman & Silver（1989，J Clin Clin Psychol——J Consult Clin Psychol 57(3):349-357）系统检视西方丧亲四大迷思：抑郁不可避免／痛苦必须体验、不痛苦即病态／必须「work through」处理哀伤／恢复与解决终将到来；结论：可用实证 \"fails to support and in some cases contradicts them\"，且这些错误假定 \"may lead others to respond to those who have endured loss in ways that are unhelpful\"。","rel":["sadness"]},{"id":"PSY-GR-005","title":"文化与哀伤：表达规范、求助门槛与「病」的边界","level":"D","summary":"哀伤本身是普世体验、症状结构跨文化也能测出来；但「该哭多久、能不能哭、什么时候算病、该不该求助」的规范中西差异很大——产品别拿表达强度当恢复尺。","content":"【普世的一面】Killikelly 等（2026，Glob Ment Health）在肯尼亚、纳米比亚、南非三国验证 ICD-11 用 IPGDS：心理测量成立、探索性因子分析支持单因子——症状结构在相当不同的文化里能测出来；三国疑诊率（肯尼亚 9.63%、南非 6.85%、纳米比亚 5.34%）与全球均值 9.8% 接近，尽管这些国家丧亲暴露显著更高；共同风险因子=与逝者关系亲近+非正常死亡（与西方样本方向一致），肯尼亚/南非另见经济困难升风险。【文化的一面】Eisma（2023）指出：现有 PGD 效度证据多来自西方、其次东亚，其他地区几近空白；","rel":[]},{"id":"PSY-GR-006","title":"产品落点：陪伴 AI 面对丧失与哀伤的回应纪律","level":"D","summary":"哀伤对话里 AI 的唯一 KPI 是「在场 + 不添乱」：不给时间表、不问进度、不劝面对也不劝放下、不说「我懂」、危机信号恒转介。","content":"纪律一【禁时间表】：不输出「五阶段」「X 个月后就会好」「走出来了」等进度叙事（阶段论实证不成立见 [[PSY-GR-001]]；社会时间表对持续悲伤的惩罚有实验证据见 [[PSY-GR-004]] Kahler 2021）。纪律二【允许暂停与摆荡】：按 DPM，逃避/不谈是适应机制（dosage of grieving，Stroebe & Schut 1999）；「今天不想聊这个」不是退步，接住即可，不追问进度。纪律三【不两头劝】：既不推「你要面对/哭出来/处理它」（Wortman & Silver 1989：必须处理是迷思），也不推「别想了/放下吧」（持续性联结见 [[PSY-GR-002]]：继续联结是常态且内化型联结有益）；","rel":["sadness"]},{"id":"PSY-SL-001","title":"睡眠不足对情绪的影响：元分析证据（好的感受先消失，不是「什么都不好」）","level":"A","summary":"没睡好时情绪更容易崩、快乐更容易消失，这是有元分析支持的生理倾向，不是用户「意志力差」——回应先接住这个正常化解释","content":"Palmer 等 2024 年系统综述+元分析（预注册）汇总 50 余年实验证据，结论要分两半看，不能笼统说「睡眠不足让人难受」：**所有形式的睡眠丧失（整夜不睡 / 部分限制 / 碎片化）一致造成**——① 积极情绪下降（标准化均差 SMD = -0.27 至 -1.14，是所有指标里最稳的）；② 焦虑症状上升（SMD = 0.57-0.63）；③ 对情绪刺激的唤醒反应钝化（SMD = -0.20 至 -0.53）。而**消极情绪、抑郁症状、情绪效价判断的结果是「混合」的**——取决于睡眠丧失的类型、剥夺量（存在非线性：少睡一点和多睡少很多不是一回事）以及被限制的是 REM 还是慢波睡眠。","rel":["joy","fear"]},{"id":"PSY-SL-002","title":"失眠与抑郁/焦虑的双向关系：失眠更像「先行风险因素」，反向证据不稳","level":"A","summary":"睡不好常常走在抑郁前面（风险约 2-3 倍）——但「所以失眠治好了抑郁就好了」不是可推论的因果；抑郁反过来预测失眠的证据反而更弱","content":"**正向（失眠→抑郁）证据强**：Baglioni 等 2011 元分析（21 项纵向研究）随机效应 OR=2.60（95% CI 1.98-3.42），固定效应 OR=2.10（1.86-2.38）——「无抑郁的失眠者日后患抑郁风险约为无睡眠困难者的两倍」；Li 等 2016（34 项前瞻队列、172,077 人、平均随访 60.4 个月）合并 RR=2.27（1.89-2.71），Egger 检验提示有发表偏倚但剪补法不改变合并值；Hertenstein 等 2019（13 项研究）抑郁 OR=2.83（1.55-5.17）、焦虑 OR=3.23（1.52-6.85）、酒精滥用 OR=1.35（1.08-1.67）。","rel":["fear"]},{"id":"PSY-SL-003","title":"运动干预对抑郁/焦虑：效应真实存在，但幅度分歧大、剂量问题没有标准答案","level":"A","summary":"运动改善抑郁焦虑有元分析级证据（效应中等、不同形式 0.4-0.6 附近），但既治不了「懒得动」、也不能替代专业治疗——它是可提供的「一般信息」，不是给用户的处方","content":"**症状层面（有效，A 级）**：Noetel 等 2024 BMJ 网络元分析（218 项随机试验 495 臂 14,170 人，对比「主动对照」如常规照护/安慰剂片）——步行或慢跑 g=-0.62（95% 可信区间 -0.80 至 -0.45）、瑜伽 g=-0.55、力量训练 g=-0.49、混合有氧 g=-0.43、太极/气功 g=-0.42；**效应随规定强度递增**（高强度比低强度效应更大）；作者结论原话：这些运动形式「可与心理治疗和抗抑郁药并为核心治疗考虑」。⚠️ 同文如实记录：CINeMA 证据置信度步行/慢跑为「低」、其他形式「极低」——作者明确说明只有 1 项研究达到 Cochrane 低偏倚标准。","rel":["fear"]},{"id":"PSY-SL-004","title":"青少年睡眠时相延迟与情绪：生理是底子、屏幕是配角、抑郁效应比想象小","level":"B","summary":"青少年晚睡晚起主要是生理时相后移，不是懒；但「晚睡→抑郁」的因果比直觉弱得多——对身体说教的归因（懒/不自律）正是产品要避免的","content":"**生理底子**：Crowley、Wolfson、Tarokh & Carskadon 2018 综述（Journal of Adolescence，Brown/Carskadon 学派「完美风暴」模型 2011 之后的证据更新）梳理青春期两套睡眠调节系统的变化：睡眠压力**积累变慢**（晚睡更容易保持清醒）而**消散速度不变**（⇒ 睡眠需求不变，仍约每晚 9.25 小时）；昼夜节律系统随发育成熟**整体后移**，褪黑素 onset 在 10 年级比 9 年级晚约 40 分钟（Carskadon 等 1998，经该综述转述）。结果是青少年的生物钟想晚睡、学校逼早起，净睡眠被两头挤压。","rel":[]},{"id":"PSY-SL-005","title":"生活建议红线：睡眠卫生是「一般信息」不是治疗，运动是「核心治疗」之一——陪伴 AI 一概不处方","level":"A","summary":"AI 可以讲睡眠卫生一般常识、可以讲 WHO 活动量建议，但绝不能暗示「照这个做就能治好失眠/抑郁」——因为指南明说睡眠卫生单独用治不了失眠，运动是「核心治疗」之一（是治疗，不是建议）","content":"本卡规定陪伴产品在睡眠/运动话题上的**话术红线**，每条硬事实都有官方出处：**硬事实① 失眠障碍的一线治疗是专业干预**。AASM 2021 临床实践指南（Edinger 等，美国睡眠医学会，GRADE 分级）：**多成分 CBT-I 为成人慢性失眠障碍的 STRONG（强）推荐**（基于 49 项研究 66 项 RCT 的系统回顾）；刺激控制、睡眠限制、放松疗法、简短疗法均为 CONDITIONAL（条件）推荐。「慢性失眠障碍的诊断基于 ICSD-3 或 DSM-5 标准与完整病史」——诊断本身就是临床行为。**硬事实② 睡眠卫生单独用 ≠ 治疗**。","rel":["calm"]},{"id":"PSY-SL-006","title":"产品落点：用户说「睡不着」「不想动」时——先接住、再给选项，永远不推销建议","level":"B","summary":"失眠/不想动的自述，第一反应永远是情绪确认+正常化，然后陪用户挑「可选可不做的小动作」；建议权在用户手里，处方权在专业人士手里","content":"本卡是 SL 域五条研究（[[PSY-SL-001]]~[[PSY-SL-005]]）的产品端收敛。五条原则=一层实证底+一层设计映射。**原则一【先共情，再谈睡眠/运动】何时说**：未被寻求的建议易被归因为建议者自利、降低采纳与学习（库内 [[PSY-DC-007]] 已收一手证据）；自主支持型回应（给选择、给理由、承认感受、非控制语言）在 184 个数据集元分析中与需要满足和更好健康结果相连（[[PSY-DC-006]]）。设计映射：用户说「最近失眠严重」时先确认情绪与影响（「影响白天状态了吗」这一层已经算事实核查而非治疗盘问），**不立即进入睡眠卫生清单**。","rel":[]},{"id":"PSY-RS-001","title":"弹性是动态过程，不是人格特质","level":"A","summary":"弹性不是\"内心强大\"这种固定标签，而是人在逆境下\"稳得住、过得去、事后还能回来\"的一段轨迹——同一个人在不同人生阶段、不同打击下，弹性可以完全不同。","content":"心理学里\"心理弹性（resilience）\"已被鸡汤化用烂，严谨定义其实朴素：**在重大逆境背景下保持良好适应**，且注意两点——它是过程不是属性；\"良好适应\"不等于\"没有症状\"（Luthar 经典定义，经 Saltzman 2011 全文逐字转引）。Bonanno 实验室把弹性做成可测量的\"轨迹\"：横断面研究把所有人混在一起算平均，潜变量轨迹建模则追问\"每个人随时间的曲线形状一样吗\"。2002 年 JPSP 前瞻研究是范本：丧偶前数年即开始测量 205 人，丧偶后第 6、18 个月复测，识别出五条轨迹——常见哀伤、慢性哀伤、慢性抑郁、丧偶期间好转、韧性；结论反常识：**常见哀伤反而少见，最常见的是韧性轨迹**；","rel":[]},{"id":"PSY-RS-002","title":"创伤知情（TIC）：SAMHSA 六原则与对话转译","level":"A","summary":"创伤知情不是\"把人当病人\"，而是默认任何人都可能带着创伤历史，从而把安全、可信透明、同伴、协作、赋权选择、文化性别这六件事做进每一次互动。","content":"SAMHSA 对创伤的操作定义（逐字）：\"个体经历为身体或情感上有害、或危及生命的事件、系列事件或一组处境，并对个体的功能与身心社灵安康造成持久不良影响\"。六原则官方名称与对话转译：① **安全 Safety**——隐私边界说清（这段对话存哪、谁能看）、退出随时可用、不用\"不说就是不信我\"施压；② **可信与透明 Trustworthiness & Transparency**——角色透明：我是 AI、会什么不会什么，不确定就说不确定；③ **同伴支持 Peer Support**——AI 不是同伴，只能指向真人支持团体/同伴资源；","rel":[]},{"id":"PSY-RS-003","title":"PTSD 四簇症状与\"该看医生了\"的识别边界","level":"A","summary":"PTSD 在 DSM-5/DSM-5-TR 里是四簇症状——再体验、回避、唤醒与反应、认知与心境——须\"持续 1 个月以上且严重到影响生活\"才够线；陪伴 AI 的任务是识别\"到线了\"并平静建议就医，不是下诊断。","content":"诊断门槛（NIMH 逐字口径）：成人需以下四类全部满足且持续至少 1 个月——再体验症状 ≥1 条、回避症状 ≥1 条、唤醒与反应症状 ≥2 条、认知与心境症状 ≥2 条，并严重到影响关系或工作等日常功能，且不能归因于药物、物质使用或其他疾病。症状通常在事件后 3 个月内出现，也可更晚；部分人 6 个月内恢复，也有人持续 1 年以上；终生患病约每 100 人中 6 人（美国国家 PTSD 中心口径），女性高于男性；常与抑郁、物质使用、焦虑障碍共病。四簇速览（用于\"听懂用户在说什么\"，不是用于归类）：再体验=闪回、噩梦、闯入记忆、躯体应激反应；回避=躲开人事物、躲开相关念头感受；","rel":["fear","calm"]},{"id":"PSY-RS-004","title":"ACE 童年不良经历：剂量反应证据与流行化误用（两方并陈）","level":"D","summary":"ACE 研究证实的是\"童年逆境类别数与成年后一串健康风险相关、大致呈剂量反应\"；把它读成\"4 分以上注定生病\"是流行化误用——原设计是单中心回顾性横断面问卷，效应异质性大，量表还漏掉了歧视等当代逆境。","content":"**支持方（剂量反应真实存在）**：Felitti 1998 原始研究向加州 Kaiser 一家 HMO 完成体检的 13,494 名成人寄问卷，9,508 人（70.5%）回应；超过一半报告 ≥1 类、四分之一报告 ≥2 类童年逆境；≥4 类者与 0 类者相比，酗酒/吸毒/抑郁/自杀未遂风险高 4–12 倍，吸烟/自评健康差/≥50 名性伴/性病高 2–4 倍，缺乏运动与重度肥胖高 1.4–1.6 倍，且与缺血性心脏病、癌症、慢阻肺、骨折、肝病均呈\"分级关系\"（P<.001）。","rel":[]},{"id":"PSY-RS-005","title":"创伤后增长（PTG）：建构、证据与方法学批评（两方并陈）","level":"D","summary":"很多人报告\"苦难让我成长\"，但\"报告出来的成长\"与\"真实发生的成长\"是两回事——经典研究发现自陈增长分与前后测真实变化基本无关，还常与痛苦升高同路；正负结果可以并存。","content":"**建构方**：Tedeschi & Calhoun 2004 目标论文把 PTG 定义为\"作为逆境/创伤/极具挑战处境之结果的持久积极心理变化\"（Jayawickreme 2021 摘要逐字口径），包含自我感知、关系、人生哲学等维度的积极转变，是创伤心理学最具知名度的积极向构念之一（Crossref 记录该文被引 5,700+ 次）。**批评方（三层）**：① **测量层**——Frazier 2009 让 122 名大学生前后测两次，比较两测间的真实变化与 PTGI 量表分：PTGI 与真实增长基本无关；且\"感知到的增长\"与痛苦升高相关，而\"真实增长\"与痛苦下降相关，提示两者是不同过程；","rel":[]},{"id":"PSY-RS-006","title":"产品落点：用户披露创伤时的回应纪律","level":"C","summary":"用户说出\"我小时候……\"时，心屿只做四件事：接住情绪、不问细节、不给英雄叙事、平静把门指向专业帮助；其余一律不做。","content":"**六条纪律**：① 不追问细节——不问\"他做了什么/有几次/你几岁\"；可说的是\"你愿意说多少都可以，不想说细节完全没问题\"（Slack 2026：幸存者明确反感逼问式提问与突兀排序）。② 不渲染英雄叙事——禁\"你会更强大/这是礼物\"（依据 [[PSY-RS-005]]）。③ 不评估不打分——不问 ACE 数目、不输出创伤严重程度、不贴 PTSD 标签（依据 [[PSY-AP-015]]、[[PSY-RS-004]]）。④ 先情绪后信息——回应指向\"现在多难\"，不急着解释机制或塞自助技巧（依据 [[PSY-DC-007]]）。⑤ 平静给转介——把专业帮助说成普通选项而非紧急事件：\"如果想找个专业的人聊聊，我可以告诉你怎么找\"；","rel":["calm"]},{"id":"PSY-NG-001","title":"愤怒的评价指纹：目标受阻 + 他人过错指派","level":"A","summary":"愤怒不是「强度更高的负性情绪」，而是「他人能动性归因 + 高确定性/高控制感」这一特定评价组合的产物，因此在评价维度上与恐惧、悲伤正交可分。","content":"评价理论把愤怒的操作定义为：事件与动机不一致（目标受阻）、且被指派为**他人**能动性所致（可归责），同时伴随较高的确定性与控制潜在力；恐惧/悲伤可同样目标受阻，但能动性归于情境或自身、控制潜在力低，故三者不是同一维度的不同分值。一手实证：Roseman, Spindel & Jose (1990, JPSP 59(5):899-915) 以 16 种情绪的假设-检验范式证实情境状态（动机一致/不一致）、奖惩、概率、力量、正当性与能动性（情境/他人/自我）六维与特定情绪存在可预测配对（部分未获支持处需修正理论）；","rel":["sadness","anger","fear"]},{"id":"PSY-NG-002","title":"「发泄出来就好了」：攻击性宣泄不降攻击，披露性书写有微弱获益","level":"D","summary":"打沙袋、吼出来、写痛骂信若与**反刍**同框会抬高愤怒与攻击，而「把感受写下来」类披露的获益是小效应且与攻击性发泄不同构。","content":"一手实验：Bushman (2002) 让被激怒者打沙袋，同时想「激怒我的人」（反刍组）或想「健身」（分心组），并有未打沙袋对照组——反刍组事后自评愤怒更高、对激怒者施予噪音爆轰的攻击最强，分心组次之，对照组最低；作者结论为「什么都不做比发泄更有效」，直接反驳宣泄假说。同向旧证：Geen, Stonner & Shope (1975) 的题目标题即结论「攻击为攻击所强化：反对宣泄假说的证据」。","rel":["anger"]},{"id":"PSY-NG-003","title":"冲突升级信号与生理淹没：结论全部来自已婚样本","level":"D","summary":"可用的稳定部分是「冲突后能否转入正性互动」比冲突当期更能预示关系走向；不可用的部分是把预测百分比与「20 分钟冷静期」当普适事实。","content":"可观察信号与生理线：Gottman & Levenson (1992) 把负性互动四类模式（通称「四骑士」）与冲突期生理唤起并列为关系解体预测源，题录即把「行为—生理—健康」并置为解体预测变量，这是「淹没（flooding）」概念的一手锚。最硬的量化证据来自 1999 年「反弹」研究：同一批伴侣先做冲突对话再做正性对话，4 年内离婚用冲突对话情感变量预测为 82.6% 准确，而用**冲突后正性反弹对话**预测为 92.7% 准确，且两次对话的情感高度一致——产品应据此把信号从「吵没吵」移到「吵完能不能自己降温、转入正性互动」。","rel":[]},{"id":"PSY-NG-004","title":"非暴力沟通的实证基座：流传度远高于证据强度","level":"C","summary":"四步（观察—感受—需要—请求）被验证的只是「短期抬升自报同理心」这一窄结论，不是「能化解冲突」。","content":"可核到的是少数小随机试验：Epinat-Duclos et al. (2021) 医学生 NVC 教育、Nosek et al. (2014) 护理教育试点，主结局均为自报同理心；2026 年 BMC Medical Education 急诊教学试验（仅二手摘要）报 NVC 组 n=100 对主动对照 n=98，JSPE 组别×时间 β=16.95（95%CI 15.40-18.50，P<0.001）、SCCG β=4.44（3.41-5.47），但未前瞻性注册、只测课后即刻。","rel":[]},{"id":"PSY-NG-005","title":"「愤怒是次级情绪」：来源是治疗框架，且分类学内部自相矛盾","level":"D","summary":"「愤怒背后总有别的感受」是有用的探问姿势，不是已验证的情绪结构事实。","content":"命题两条来源都在治疗/通俗侧：情绪聚焦疗法（EFT）把情绪分原发（适应/不良适应）、次级（对原发情绪的反应，难调节、带防御功能）、工具性三类，Pascual-Leone et al. (2013) 据此明说「问题性愤怒从来不是原发情绪」——这是治疗构念而非测量结论；通俗读物再把它简化成「愤怒冰山」。对立一方：情绪觉知文献把「对冒犯或不义的反应」列为原发情绪，反把焦虑、羞耻、紧张、抑郁、挫败列为次级，愤怒归属正好相反。可核实证只支持「原发/次级」是可操作变量：James et al. (2023, Sensors 23(6):2999) 以次级情绪为目标做共情语音合成，听者识别命中率 >65%；","rel":["anger","fear"]},{"id":"PSY-NG-006","title":"产品落点：用户表达愤怒时的回应纪律（六条，均不构成治疗建议）","level":"C","summary":"先确认+归还选择权、不灭火、不抢先讲道理、不陪着攻击第三方、禁「你别生气」类无效化、危机恒转介且不做风险评估。","content":"①先确认并归还选择权（自主支持元分析 184 个数据集，控制型情境相反；「必须/应该」实测抬升愤怒 r=.21）；②不灭火＝不催快好、也不叫用户硬压（重评优于硬憋，「压感受/别想了」对主观体验近乎无效 d=-0.04/-0.12；平复需要时间，反刍才拉长恢复）；③不抢先讲道理（未被寻求的建议易被归因自利、降采纳；过多实用建议降「被听见」感）；④不站用户去攻击第三方：有研究显示实验室里「宣泄/攻击替代品」并不降温，陪着骂不能当降级手段；⑤禁「你别生气/别激动」——不承认情绪＋命令抑制两条坑各有实验证据；确认降愤怒/羞耻心率有效但存在情绪特异性，别当万能降温键；⑥危机词恒转介、永不输出风险等级（现有聊天体危机应答合格率 0%）。","rel":["anger"]},{"id":"PSY-RJ-001","title":"社会拒绝「像疼」吗：dACC 主张与两方质疑","level":"D","summary":"被拒会激活痛苦相关脑区，但「和身体疼痛同一条通路」不是定论，产品禁用该说法。","content":"原始 fMRI（Eisenberger 2003, Science 302(5643):290-292）：被排斥时背侧前扣带（dACC）等激活升高且与自报痛苦正相关。后续两方并陈：支持方 Rotge 等 2015 元分析（46 篇/940 人，SCAN 10(1):19-27）确认 ACC 参与社会痛苦；反对方 Cacioppo 等 2013 元分析（Sci Rep 3:2027，Cyberball，244 人）称「同一疼痛矩阵」不成立，Woo 等 2014（Nat Commun 5:5380，60 人）用多变量分类器以 92%/80% 准确率区分身体痛与被拒（摘要亦承认存在共同激活）。**产品措辞**：可说「被拒的痛很真实」；","rel":[]},{"id":"PSY-RJ-002","title":"排斥的即时后果：需求威胁模型与 Cyberball","level":"A","summary":"被忽略几分钟即伤四需求与心境；重新纳入可恢复。","content":"Cyberball 最小范式（Williams, Cheung & Choi 2000, JPSP 79(5):748-762）：被网络传球游戏中的「其他玩家」（实为程序）忽略数分钟，归属/控制/自尊/存在意义四需求与心境即降，忽略越多越差；元分析 120 项、N=11,869（Hartgerink et al. 2015, PLOS ONE 10(5):e0127002）：效应稳健量大（摘要 |d|>1.4）、不易被调节。**文化边界**：德国被试需求受损强于土耳其/中国/印度被试（Pfundmair et al. 2015, JCCP 46(4):579-596，单研究）。","rel":[]},{"id":"PSY-RJ-003","title":"分手恢复的时间轨迹与自我概念变化","level":"C","summary":"恢复无统一时间表；「14 周/3 个月」查无同行评审出处。","content":"有研究显示分手后痛苦回落快于当事人预测（Eastwick et al. 2008, JESP 44(3):800-807，体验采样，「情感预测误差」）；有研究（Slotter, Gardner & Finkel 2010, PSPB 36(2):147-160，三项研究）显示分手后自我概念清晰度下降、「不知道自己是谁」与更重痛苦相关。**警示**：「14 周」「3 个月」本轮未核到同行评审出处；「11 周」仅溯到蒙莫斯大学 155 人样本的媒体叙述（样本为分手 6 个月内者、71% 看到积极面，其未测量「恢复时长」）。**产品**：不做「几周会好」的承诺；以重建自我概念为陪伴支点（不构成治疗建议）；危机只转介、不评估。","rel":[]},{"id":"PSY-RJ-004","title":"拒绝敏感：构念、测量与亲密关系后果","level":"B","summary":"拒绝敏感=对拒绝的焦虑性预期；高分者易把模糊行为读成拒绝并敌意反应，中文版信效度良好。","content":"**拒绝敏感（RS）定义为「对拒绝的焦虑性预期」**。Downey & Feldman (1996, JPSP 70(6):1327-1343) 以情境式 RSQ 测量：每情境双评（对拒绝的焦虑 × 对接受的预期反向），高 RS 者在亲密关系中更易把伴侣模糊行为解读为拒绝信号、反应更激烈，形成「预期拒绝→敌意→真被疏远」的知觉偏差循环，关系满意度更低。中文修订（赵艳林等 2012，N=377）：保留 16 项，α=0.835、重测 0.762，与特质焦虑 r=0.478、人际敏感 r=0.394、自尊 r=-0.405。**边界**：RS 与特质/依恋焦虑中等相关，存在构念重叠批评，增量效度缺权威元分析（见待验证点）。","rel":["fear"]},{"id":"PSY-RJ-005","title":"「间歇性强化」与被已读不回：证据边界","level":"C","summary":"不确定的奖励在机制层面确有「更勾人」证据，但搬到「已读不回」只有缺环外推，产品不得据此下命令式建议。","content":"**分层看**：①**动物学习传统**——可变比率/间歇强化产生高而稳的反应率且难以消退（经典结论，本轮仅经 2025 年综述转述，未亲核原始文献）；②**人类实验**——奖励不确定性（随机 vs 确定）显著提高对奖励追求的投入（Shen, Fishbach & Hsee 2015, J Consum Res 41(5):1301-1315，「Motivating-Uncertainty Effect」）；","rel":[]},{"id":"PSY-RJ-006","title":"产品落点：失恋与表白被拒场景的回应纪律","level":"C","summary":"接住痛、不贬低对方、不劝放下、不给时间表、不用「下一个更好」、不说「我懂」；选择权还给用户，危机恒转介。","content":"**六条纪律**：①**接住「被拒的痛很真实」，但不说「大脑分不清两种痛」**——拒绝之痛的神经机制是两方并陈的 D 级（[[PSY-RJ-001]]），措辞上限据此定。②**不贬低对方、不陪着骂**——陪着攻击第三方不降温（[[PSY-NG-006]] ④ 的实验室证据），也会让用户日后把自己说过的话当成负担。③**不劝放下、不给时间表**——「14 周/3 个月」查无同行评审出处（[[PSY-RJ-003]]）；哀伤篇的「不给时间表、不问进度、不劝面对也不劝放下」原样迁移（[[PSY-GR-006]]、[[PSY-GR-001]] 禁用阶段叙事）。","rel":[]},{"id":"PSY-HK-001","title":"自我污名：把公众刻板装进自己体内","level":"C","summary":"自我污名是内化的疾病刻板信念，SSOSH 测的是「求助这件事让我觉得自己低人一等」，它与求助回避同向相关但因果方向未定。","content":"自我污名=把公众对精神障碍的刻板信念转向自身；其测量工具 SSOSH（Self-Stigma of Seeking Help）出自 Vogel, Wade & Haake (2006) 建量表论文（Journal of Counseling Psychology 53(3):325-337, DOI:10.1037/0022-0167.53.3.325，题录经主进程 Crossref 二次实取一致）。","rel":[]},{"id":"PSY-HK-002","title":"「想不想求助」和「会不会去求助」是两套题、两套结论","level":"B","summary":"求助态度量表分数与真实求助（或交往意愿）可以反向变动，意向-行为落差是实测存在而非修辞。","content":"测量谱至少分两支：求助态度（如 ATSPPH-SF，Attitudes Toward Seeking Professional Psychological Help–Short Form）与自我污名（SSOSH）——两者在同一项研究里并用（Lee et al., 2026, BMC Medical Education 26(1):748, DOI:10.1186/s12909-026-09091-0, PMID:41918113），说明「想不想」与「会不会」被当作不同构念。","rel":[]},{"id":"PSY-HK-003","title":"削减污名：接触式与教育式谁有效，生物医学标签是双刃","level":"D","summary":"生物医学标签确实降低「责怪」，但同时加重预后悲观；接触式与教育式干预的结局高度依赖维度与人群，短程项目常改态度不改污名。","content":"反方与正方并陈——Kvaale, Haslam & Gottdiener (2013) Clinical Psychology Review 33(6):782-794（DOI:10.1016/j.cpr.2013.06.002, PMID:23831861）汇总 28 项实验研究、四个元分析（各分析 N=1207–3469），生物基因解释**降低自责/责备 Hedges g=−0.324（p=.001；异质性 Q=66.850, p<.001, I²=80.554；该子分析含 14 份报告/40 个效应量/合计 N=2326）**，这是「贴标签有帮助」一派的真实收益；","rel":[]},{"id":"PSY-HK-004","title":"男性规范与面子：求助意愿的两条文化抑制链","level":"A","summary":"男性「坚强/自主」规范与东亚面子-家丑顾虑是两条相互独立但同向的求助抑制路径，前者的干预靶点是自我污名，后者在本库缺一手实证。","content":"跨源一致的最硬结论是：男性平均比女性持更消极的专业心理求助态度，且性别角色冲突越高、社会污名与自我污名越强，求助态度越差——此链在北美（男大学生、无家可归男性）与东南亚华人样本中均被复现，方向稳定（Addis & Mahalik 2003 理论+实证综述；Wahto & Swift 2014 性别角色冲突与污名路径；Loganathan & Foo 2020 马来西亚样本同向）。中国文化面（面子、家丑不外扬、躯体化表达优先于情绪词汇）本轮**未取到带 DOI 的一手中文实证**，只有中文二级文献题录（男大学生性别角色冲突经求助污名中介影响求助态度；","rel":[]},{"id":"PSY-HK-005","title":"网络与 AI 已成青少年求助链条的前段","level":"C","summary":"青少年确实把网络/AI 放在求助路径的第一段（美国 12-21 岁约五分之一用过 AI 取心理建议、多数瞒着成人），但「先 AI 后真人」目前是结构外推。","content":"一手可用数据：RAND 全美代表性调查（2025-11 施测，n=1009，12-21 岁）报 19.2% 曾用 AI 聊天机器人在悲伤/愤怒/压力下获取心理健康建议，一年前为 13.1%；其中 63% 从未向任何人透露此事，43% 每月至少一次，92% 认为建议「有些/非常有帮助」（研究者本人提醒这可能反映迎合倾向而非质量）；女性高于男性、18-21 岁高于 12-17 岁；**近半年曾与医生谈过心理健康者更可能用 AI**（相关，不是转介证据）。中国侧只有非同行评审调查（中国青少年研究中心 2025：7 省 8563 名中小学生，超六成用过 AI、近半数烦恼时求助 AI 而非身边人、超两成只想和 AI 聊）。","rel":["sadness","anger"]},{"id":"PSY-HK-006","title":"怎么把「建议去求助」说得可接受","level":"C","summary":"给选择权 + 去标签 + 具体低摩擦下一步 + 危机轮恒转介不做风险评估，是可接受度最高的组合，但必须由产品 A/B 验证。","content":"四条操作原则及其依据边界：①**给选择权、不施压**——求助的最大阻力是自我污名与被评判感，命令式/严重化措辞会同时抬高两者（本库 [[PSY-DC-005]] 心理抗拒一支同向）。②**去标签**：避免诊断化用词，把「你可能抑郁了」换成可否认的行为描述；网络式教育/接触类干预被报为能改善知识与污名态度（Nazari et al. 2023, BMC Psychiatry 23(1), DOI:10.1186/s12888-023-05143-7，题录经主进程 Crossref 二次实取），但一项中文元分析明确指出**未证实对实际求助行为的促进**（态度≠行为，原始出处未核，见待验证点），故话术优化的成功指标应设成「点击热线/完成一","rel":[]},{"id":"PSY-PR-001","title":"拖延的机制之争：时间动机理论 vs 情绪调节失败 vs 测量效度质疑","level":"D","summary":"拖延最稳的相关因素是任务厌恶、任务延迟、自我效能、冲动性和尽责性（自控/易分心），而神经质与感觉寻求只有弱关联；但「它是时间计算出错还是情绪调节失败、以及现有量表到底有没有测到拖延」都还在吵，别当定论讲给用户。","content":"【机制有分歧，别当定论】最稳的相关因素：Steel (2007, Psychological Bulletin 133(1):65-94，整合 691 条相关) 摘要逐字结论——神经质、逆叛性、感觉寻求与拖延「只有弱关联」；**强而一致的预测因素是任务厌恶、任务延迟、自我效能、冲动性，以及尽责性及其自控/分心/组织/成就动机 facet**；作者据此提出「时间动机理论」（期望论与双曲折扣的整合混合体），并称拖延的流行度「似乎在上升」。复现：Netzer Turgeman & Pollak (2026) 预注册 SEM（N=640 网络 recruited 成人，非大学生）显示「对延迟的敏感」与「任务主观价值低」是显著中介路径。","rel":[]},{"id":"PSY-PR-002","title":"「拖延是情绪调节问题，不是懒惰」：实证强度与自我宽恕/自我同情这支","level":"B","summary":"训练「容忍并改变负性情绪」的能力在随机对照研究里能降低拖延，情绪调节困难与拖延的关联在控制焦虑抑郁后仍在，所以把拖延解释成情绪调节问题比解释成懒惰更接近数据；但「原谅自己上一次拖延会少拖」目前只有前瞻性相关证据。","content":"【硬数据在最前】①Eckert, Ebert, Lehr, Sieland & Berking (2016, Learning and Individual Differences 52:10-18) 三项研究递进：横断=情绪调节技能与拖延相关且经「容忍负性情绪」中介；交叉滞后=「改变负性情绪」的能力预测后续更少拖延（反向亦有）；**双臂 RCT=系统训练「容忍+改变负性情绪」技能降低了拖延**。Rozental 等 2018 表 1 记录该 RCT 细节：网络无引导情绪调节训练 2 周，情绪调节组 44 vs 等待组 39，结局用 GPS-简版（α=0.80），样本是**社区自转介的一般人群而非大学生** ⇒ 外推到学生是限制。","rel":["fear"]},{"id":"PSY-PR-003","title":"学业倦怠：三成分的官方口径、学生情境外推、与抑郁的区分之争及中国大学生数据","level":"D","summary":"官方把 burn-out 限定在职业情境、且明文不应外推到生活其他领域，所以「学业倦怠」是学生量表借用职业构念的外推产物；它是不是独立于抑郁学界仍在吵，而所有倦怠/抑郁百分比都随口径与年份大跳，引用必须先报口径。","content":"【官方口径先行】ICD-11 原文：「Burn-out is a syndrome conceptualized as resulting from chronic workplace stress that has not been successfully managed」，三维度为精力耗竭、对工作心理上疏离/犬儒、职业效能降低，且**「Burn-out refers specifically to phenomena in the occupational context and should not be applied to describe experiences in other areas of life.」**（W","rel":[]},{"id":"PSY-PR-004","title":"就业与未来不确定性焦虑：中国大学生情境的构念、测量与薄干预证据","level":"C","summary":"中国大学生的「就业焦虑」有可核对的本土测量（26 题四维）并与学业压力、决策拖延、职业决策自我效能相连，但因果方向不明、干预证据极薄且效应量自相矛盾，陪伴 AI 不该据此给职业建议。","content":"【构念与测量（本土可核对）】Yang 等 (2025, Front Psychiatry 16:1602808，N=1,124 中国三所大学本科生，横断) 使用「大学毕业生就业焦虑问卷」：依张亚壮等结构，26 题、4 维=求职竞争压力/就业支持缺乏/低自信/对就业前景担忧，5 点计分，本研究 α=0.930，四因子 CFA χ²/df=2.85、CFI=0.927、TLI=0.912、RMSEA=0.059、SRMR=0.049（取自该文方法节，全文实读自 PMC12170629）。硬数据（C 级）：学业压力正向预测就业焦虑 B=0.421，心理韧性部分中介、间接效应占总效应 19.50%。","rel":["fear"]},{"id":"PSY-PR-005","title":"完美主义与自我批评在学业情境：社会割裂模型、后果与测量之争","level":"D","summary":"完美主义要拆成「担忧面 vs 高标准面」再谈——担忧面（含社会规定的「别人要我完美」）稳定连到更差的结果，而「高标准」本身可以与学业成就正相关，且现有学业完美主义量表常把两者混测。","content":"【构念起源】Hewitt & Flett (1991, JPSP 60(3):456-470) 提出完美主义是多维且社会性的：自我导向（SOP）、他人导向（OOP）、社会规定 SPP=感到别人对我要求完美；摘要逐字记录「4 项研究证实多维且可可靠测量」，并在 77 名精神科患者中显示三维度与人格障碍及失调指标差分关联。","rel":[]},{"id":"PSY-PR-006","title":"产品落点：用户说「什么都做不完 / 我是不是废了 / 找不到工作」时的回应纪律","level":"C","summary":"拖延倾诉轮里「先接情绪、把拆小当可选项由用户挑、绝不施压」是有对照试验与元分析支撑的方向，而「效率说教/时间管理清单」在拖延结局上目前拿不出可靠证据，需要产品 A/B 亲测才能定。","content":"【先给证据再给规则】①效率说教不是循证首选：Glick & Orsillo (2015, JEP:General 144(2):400-409, 大学生 RCT) 直接对照时间管理与接纳行为干预——摘要逐字：「虽有一条趋势提示时间管理组完成了更多指定阅读，但**未揭示拖延上的组间差异**」，而接纳取向干预对高度重视学业的学生最有效。②整体干预效应小且不稳：Rozental 等 (2018) 合并 12 项 RCT / 21 对比 / N=718（443 治疗、275 对照），post-treatment g=0.34 [0.11,0.56]，I²=61.14%；","rel":[]},{"id":"PSY-FM-001","title":"孝道与家庭期望：双元孝道模型及「期望—抑郁」的中国证据","level":"B","summary":"孝道不是笼统的「好」或「坏」——互惠性孝道稳定关联更好适应，权威性孝道对心理症状总体为零关联；父母期望则能让「成绩与抑郁同时升高」。","content":"【硬数据先行】双元孝道模型把孝道分互惠性（RFP：情感报恩）与权威性（AFP：角色义务服从）两维，反对笼统评价（Yeh & Bedford 2003, Asian J Soc Psychol 6(3):215-228）。定量综合：RFP 与抑郁、焦虑、攻击、自伤等心理症状负相关；AFP 与心理症状总体无关、与自杀负相关、与进食障碍正相关（Han & Cheung 2024, 17 项中韩青少年系统综述+元分析）；另独立元分析（21 项、11,775 人、40 效应量）显示 RFP 与 AFP 均与生活满意度正相关，效应受年龄/年份/地区调节（Zheng et al. 2025）。","rel":["fear"]},{"id":"PSY-FM-002","title":"父母心理控制：构念、测量与「中等强度但稳定的代价」","level":"A","summary":"心理控制（内疚诱导、爱的撤回、侵入）不是「管得严」——它预测抑郁与焦虑的中等强度上升，而自主支持预测情绪与学业变好，美中样本方向一致。","content":"【硬数据先行】构念与测量：Barber 1996 把心理控制从「行为控制」中分离（PCS-YSR 量表源头，Child Development 67(6):3296）；Soenens & Vansteenkiste 2010 升级为「妨碍自主需求满足的教养」（Developmental Review 30(1):74-99）。元分析（95 项、10-20 岁）：子女感知的心理控制与抑郁、焦虑呈中等强度相关，受文化（个体/集体主义）、性别、年龄、发表状态调节（Chyung et al. 2021, Marriage & Family Review 58(2):158-197）。","rel":["fear"]},{"id":"PSY-FM-003","title":"亲子冲突的正常化与「边界」：轨迹的实证与成年期证据缺口","level":"B","summary":"亲子冲突并非常识里的「青春期暴增」——频率随年龄下降、情绪强度早→中期上升，冲突本身可以是关系再谈判的机制；成年后的过度介入则与更差适应相关。","content":"【硬数据先行】元分析（Laursen, Coy & Collins 1998, Child Development 69(3):817-832）：不支持「冲突先升后降」常识——冲突频率与总量从青春早期→中期→晚期持续下降；情绪强度从早期到中期上升、随生理成熟单调上升；方向在不同亲子组合与报告者间一致。功能视角：冲突被视为责任再分配与关系再谈判机制，能在正负情绪间灵活切换的组合反而适应更好（Branje 2018, Child Development Perspectives 12(3):171-176）；「青春期是否冲突期」取决于冲突定义与数据来源（Steinberg 2001, JRA 11(1):1-19）。","rel":[]},{"id":"PSY-FM-004","title":"三角化与「被夹在中间」：父母冲突经孩子中转成自责与关系损伤","level":"B","summary":"「被夹在父母中间」（传声筒/裁判/盟友）与父母冲突稳定相关（r≈.40），并预测自责上升与亲子关系变差——影响常是「中转」进来的。","content":"【硬数据先行】元分析：49 项研究、N=23,336——父母冲突与「被夹感」（feeling caught/三角化）相关 r=.402（95%CI .366-.437）；在含成年子女样本、横断设计、子女自报中关联更强（Schrodt 2025, Human Communication Research 52(2):77-89）。经典研究：N=522（10-18 岁，离异 4.5 年后电话访谈）——被夹感与高冲突/敌意、低合作养育相关；与双方都亲近则被夹感低；父母高冲突时双居住安排更易被夹；","rel":[]},{"id":"PSY-FM-005","title":"产品落点：用户说「我妈又说我…」时的回应纪律","level":"C","summary":"先接住情绪、不评价家人、不劝「都是为你好」、不教对抗、把选择权交还用户；涉家暴/自伤风险立即转介，只转介不评估。","content":"【纪律与依据】①**先确认、不无效化**：实验显示无效化回应显著抬高负性情绪、心率与皮电，确认性回应相反（Shenk & Fruzzetti 2011, JSCP 30(2):163-183）⇒「这有什么好难过的」类禁语。②**禁「父母都是为你好」**：它同时是无效化与替用户定义感受，会触发心理抗拒（[[PSY-DC-005]]）。③**不替用户评判家人、不教对抗、不替做决定**——自主支持对应跨国纵向中情绪/学业功能提升，控制型回应反之（[[PSY-FM-002]]；Wang et al. 2007）。④**承认两难**：「想独立」与「想被父母认可」可同时成立，不逼站队。","rel":["sadness"]}]};
